            finalDiagnostics = finalDiagnostics with
            {
                ResolvedGiSettings = ResolvedGiSettingsMetadataFactory.Create(finalDiagnostics)
            };
            GiWarningEvaluationResult giWarningEvaluation = _giWarningEvaluator.Evaluate(finalDiagnostics);
            IReadOnlyList<GiDiagnosticWarning> giWarnings = GiDiagnosticWarningFactory.Create(
                finalDiagnostics,
                giWarningEvaluation,
                giFeatureStates);
            GiBlackFrameMetrics blackFrameMetrics = giWarningEvaluation.BlackFrame;
            return finalDiagnostics with
            {
                GiWarnings = giWarnings,
                GiBlackFrameMetrics = blackFrameMetrics,
                // Retain legacy fields for existing overlays/capture consumers, but source them
                // from the calibrated stateful evaluator rather than the old one-pixel rule.
                DdgiBlackFrameSuspect = blackFrameMetrics.LargeAreaBlackout ? 1 : 0,
                DdgiBlackFrameAfterRecenter = blackFrameMetrics.LargeAreaBlackout &&
                    finalDiagnostics.SimpleDdgiRecentered != 0 ? 1 : 0,
                DdgiBlackFrameAfterAtlasClear = blackFrameMetrics.LargeAreaBlackout &&
                    finalDiagnostics.SimpleDdgiAtlasCleared != 0 ? 1 : 0,
                DdgiBlackFrameDuringFreshAtlas = blackFrameMetrics.LargeAreaBlackout &&
                    finalDiagnostics.SimpleDdgiAtlasFresh != 0 ? 1 : 0,
            };
        }

        private void RefreshValidationDiagnostics()
        {
            RendererValidationMessageSnapshot validationMessages = _context.ValidationMessageSnapshot;
            _lastDiagnostics = _lastDiagnostics with
            {
                ValidationVerboseMessageCount = validationMessages.VerboseCount,
                ValidationInfoMessageCount = validationMessages.InformationCount,
                ValidationWarningMessageCount = validationMessages.WarningCount,
                ValidationErrorMessageCount = validationMessages.ErrorCount,
                ValidationFirstWarningMessage = validationMessages.FirstWarningMessage,
                ValidationLastWarningMessage = validationMessages.LastWarningMessage,
                ValidationFirstErrorMessage = validationMessages.FirstErrorMessage,
                ValidationLastErrorMessage = validationMessages.LastErrorMessage
            };
        }

        private static PerformanceCaptureCameraMetadata CreatePerformanceCaptureCameraMetadata(SceneRenderingData sceneData)
        {
            return new PerformanceCaptureCameraMetadata(
                sceneData.CameraPosition.X,
                sceneData.CameraPosition.Y,
                sceneData.CameraPosition.Z,
                sceneData.CaptureCameraYawRadians,
                sceneData.CaptureCameraPitchRadians,
                sceneData.CaptureCameraFieldOfViewRadians,
                sceneData.CaptureCameraNearPlane,
                sceneData.CaptureCameraFarPlane,
                ComputePerformanceCaptureMatrixHash(sceneData.ViewMatrix),
                ComputePerformanceCaptureMatrixHash(sceneData.ProjectionMatrix),
                sceneData.CaptureCameraCutSerial);
        }

        private static string ComputePerformanceCaptureMatrixHash(Matrix4x4 matrix)
        {
            string canonical = string.Join("|", new[]
            {
                matrix.M11.ToString("R", CultureInfo.InvariantCulture), matrix.M12.ToString("R", CultureInfo.InvariantCulture), matrix.M13.ToString("R", CultureInfo.InvariantCulture), matrix.M14.ToString("R", CultureInfo.InvariantCulture),
                matrix.M21.ToString("R", CultureInfo.InvariantCulture), matrix.M22.ToString("R", CultureInfo.InvariantCulture), matrix.M23.ToString("R", CultureInfo.InvariantCulture), matrix.M24.ToString("R", CultureInfo.InvariantCulture),
                matrix.M31.ToString("R", CultureInfo.InvariantCulture), matrix.M32.ToString("R", CultureInfo.InvariantCulture), matrix.M33.ToString("R", CultureInfo.InvariantCulture), matrix.M34.ToString("R", CultureInfo.InvariantCulture),
                matrix.M41.ToString("R", CultureInfo.InvariantCulture), matrix.M42.ToString("R", CultureInfo.InvariantCulture), matrix.M43.ToString("R", CultureInfo.InvariantCulture), matrix.M44.ToString("R", CultureInfo.InvariantCulture)
            });
            byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
            return Convert.ToHexString(hash).ToLowerInvariant();
        }

        internal static string ComputePerformanceCaptureSceneStateHash(
            SceneRenderingData sceneData)
        {
            if (sceneData == null)
                throw new ArgumentNullException(nameof(sceneData));

            // Restrict this identity to stable content and producer revisions.
            // Visibility, frame indices, timings, and scheduler populations are
            // intentionally excluded so two equivalent steady frames match.
            string canonical = string.Join("|", new[]
            {
                sceneData.SceneContentRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.GiTransportMaterialRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.DdgiEmissiveSourceRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.DrawPacketRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.DirectionalShadowMeshletDrawSignature.ToString(CultureInfo.InvariantCulture),
                sceneData.LocalShadowMeshletDrawSignature.ToString(CultureInfo.InvariantCulture),
                sceneData.ObjectCount.ToString(CultureInfo.InvariantCulture),
                sceneData.MeshletCount.ToString(CultureInfo.InvariantCulture),
                sceneData.MaterialCount.ToString(CultureInfo.InvariantCulture),
                sceneData.TextureCount.ToString(CultureInfo.InvariantCulture),
                sceneData.LightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.DirectionalLightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.LocalLightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.GeometryDecalObjectCount.ToString(CultureInfo.InvariantCulture),
                sceneData.CaptureSceneName ?? string.Empty
            });
            byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
            return "sha256:" + Convert.ToHexString(hash).ToLowerInvariant();
        }

        internal static string ComputePerformanceCaptureSceneAssetHash(
            SceneRenderingData sceneData)
        {
            if (sceneData == null)
                throw new ArgumentNullException(nameof(sceneData));

            // This describes authored inputs rather than the emitted draw list.
            // A controlled feature pair (for example decals on/off) therefore
            // retains one base identity, while CaptureSceneStateHash still
            // records the exact rendered state of each side.
            string canonical = string.Join("|", new[]
            {
                sceneData.SceneContentRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.GiTransportMaterialRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.DdgiEmissiveSourceRevision.ToString(CultureInfo.InvariantCulture),
                sceneData.ObjectCount.ToString(CultureInfo.InvariantCulture),
                sceneData.MaterialCount.ToString(CultureInfo.InvariantCulture),
                sceneData.TextureCount.ToString(CultureInfo.InvariantCulture),
                sceneData.LightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.DirectionalLightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.LocalLightCount.ToString(CultureInfo.InvariantCulture),
                sceneData.GeometryDecalObjectCount.ToString(CultureInfo.InvariantCulture),
                sceneData.CaptureSceneName ?? string.Empty
            });
            byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
            return "sha256:" + Convert.ToHexString(hash).ToLowerInvariant();
        }

        private void UpdateAdvancedGiRuntimeContentState(
            SceneRenderingData sceneData)
        {
            string observedProfile = ResolveCaptureScenario(
                sceneData.CaptureScenario);
            string observedScene = ComputePerformanceCaptureSceneAssetHash(
                sceneData);
            if (!_advancedGiRuntimeContentBinding.IsWellFormed)
            {
                _advancedGiRuntimeContentState = new(
                    default,
                    observedProfile,
                    observedScene,
                    false,
                    "advanced-gi-runtime-content-binding-not-configured");
                return;
            }

            bool settingsMatch = HashTextEquals(
                AdvancedGiSettingsFingerprint.Compute(
                    Settings.GlobalIllumination),
                _advancedGiSettingsFingerprint);
            bool profileMatch = string.Equals(
                observedProfile,
                _advancedGiRuntimeContentBinding.ContentProfileId,
                StringComparison.Ordinal);
            bool sceneMatch = HashTextEquals(
                observedScene,
                _advancedGiRuntimeContentBinding.SceneAssetSha256);
            string reason = !settingsMatch
                ? "advanced-gi-runtime-settings-changed-restart-required"
                : !profileMatch
                    ? "advanced-gi-runtime-content-profile-mismatch"
                    : !sceneMatch
                        ? "advanced-gi-runtime-scene-asset-mismatch"
                        : "advanced-gi-runtime-content-binding-matched";
            _advancedGiRuntimeContentState = new(
                _advancedGiRuntimeContentBinding,
                observedProfile,
                observedScene,
                settingsMatch && profileMatch && sceneMatch,
                reason);
        }

        private static bool HashTextEquals(string? left, string? right)
        {
            string normalizedLeft =
                AdvancedGiQualificationContract.NormalizeSha256(left);
            string normalizedRight =
                AdvancedGiQualificationContract.NormalizeSha256(right);
            return normalizedLeft.Length == 64 &&
                normalizedRight.Length == 64 &&
                CryptographicOperations.FixedTimeEquals(
                    Convert.FromHexString(normalizedLeft),
                    Convert.FromHexString(normalizedRight));
        }

        internal static SimpleDdgiTransportConvergenceTelemetry
            AttributeSimpleDdgiTransportRingTimings(
                SimpleDdgiTransportConvergenceTelemetry telemetry,
                long transportMicroseconds,
                long blendMicroseconds)
        {
            if (telemetry.Rings.Count == 0)
                return telemetry;

            ulong scheduledRays = 0UL;
            long scheduledProbes = 0L;
            foreach (SimpleDdgiTransportRingConvergenceTelemetry ring in telemetry.Rings)
            {
                scheduledRays = ulong.MaxValue - scheduledRays < ring.ScheduledRayCount
                    ? ulong.MaxValue
                    : scheduledRays + ring.ScheduledRayCount;
                scheduledProbes = Math.Min(
                    int.MaxValue,
                    scheduledProbes + Math.Max(0, ring.ScheduledProbeCount));
            }

            var attributed = new SimpleDdgiTransportRingConvergenceTelemetry[
                telemetry.Rings.Count];
            for (int index = 0; index < attributed.Length; index++)
            {
                SimpleDdgiTransportRingConvergenceTelemetry ring = telemetry.Rings[index];
                double transportShare = scheduledRays > 0
                    ? ring.ScheduledRayCount / (double)scheduledRays
                    : 0.0;
                double blendShare = scheduledProbes > 0
                    ? ring.ScheduledProbeCount / (double)scheduledProbes
                    : 0.0;
                attributed[index] = ring with
                {
                    EstimatedTransportMilliseconds =
                        Math.Max(0L, transportMicroseconds) / 1000.0 * transportShare,
                    EstimatedBlendMilliseconds =
                        Math.Max(0L, blendMicroseconds) / 1000.0 * blendShare
                };
            }
            return telemetry with { Rings = Array.AsReadOnly(attributed) };
        }

        internal static string CreatePerformanceCaptureBuildConfiguration(string? validationMode)
        {
            string validation = NormalizeCaptureMetadataValue(
                validationMode,
                "unavailable:validation-mode-not-reported");
            string? framework = typeof(VulkanRenderer).Assembly
                .GetCustomAttribute<TargetFrameworkAttribute>()?
                .FrameworkName;
            framework = NormalizeCaptureMetadataValue(
                framework,
                "unavailable:target-framework-not-embedded");
            return ResolveBuildConfiguration() + "; validation=" + validation + "; framework=" + framework;
        }

        internal static string ResolvePerformanceCaptureApplicationVersion()
        {
            Assembly assembly = typeof(VulkanRenderer).Assembly;
            string? informationalVersion = assembly
                .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?
                .InformationalVersion;
            return NormalizeCaptureMetadataValue(
                informationalVersion ?? assembly.GetName().Version?.ToString(),
                "unavailable:application-version-not-embedded");
        }

        internal static string ResolvePerformanceCaptureCommit()
        {
            Assembly assembly = typeof(VulkanRenderer).Assembly;
            string? sourceRevision = null;
            foreach (AssemblyMetadataAttribute attribute in assembly.GetCustomAttributes<AssemblyMetadataAttribute>())
            {
                if (string.Equals(attribute.Key, "SourceRevisionId", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(attribute.Key, "GitCommitId", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(attribute.Key, "Commit", StringComparison.OrdinalIgnoreCase))
                {
                    sourceRevision = attribute.Value;
                    break;
                }
            }

            string? informationalVersion = assembly
                .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?
                .InformationalVersion;
            return ResolvePerformanceCaptureCommit(sourceRevision, informationalVersion);
        }

        internal static string ResolvePerformanceCaptureCommit(string? sourceRevision, string? informationalVersion)
        {
            string? revision = NormalizeSourceRevision(sourceRevision);
            if (revision != null)
                return revision;

            if (!string.IsNullOrWhiteSpace(informationalVersion))
            {
                int metadataIndex = informationalVersion.IndexOf('+');
                if (metadataIndex >= 0 && metadataIndex < informationalVersion.Length - 1)
                    revision = NormalizeSourceRevision(informationalVersion[(metadataIndex + 1)..]);
            }

            return revision ?? "unavailable:source-revision-not-embedded";
        }

        internal static string ResolvePerformanceCaptureExecutableHash(
            string? executablePath = null)
        {
            try
            {
                if (!string.IsNullOrWhiteSpace(executablePath))
                    return HashPerformanceCaptureFile(executablePath);

                string? processPath = Environment.ProcessPath;
                if (string.IsNullOrWhiteSpace(processPath))
                    return "unavailable:process-path-not-reported";

                string processFullPath = Path.GetFullPath(processPath);
                string applicationDirectory =
                    Path.GetDirectoryName(processFullPath) ??
                    AppContext.BaseDirectory;
                var binaryPaths = new List<string> { processFullPath };
                binaryPaths.AddRange(Directory.GetFiles(
                    applicationDirectory,
                    "Njulf*.dll",
                    SearchOption.TopDirectoryOnly));
                binaryPaths.Sort(static (left, right) =>
                    StringComparer.OrdinalIgnoreCase.Compare(
                        Path.GetFileName(left),
                        Path.GetFileName(right)));

                // A framework-dependent .NET apphost is largely invariant when
                // managed renderer code changes. Hash a framed manifest of the
                // apphost and every application-local Njulf assembly so capture
                // provenance changes with the code that actually rendered the
                // frame. File names, rather than absolute paths, keep identical
                // builds portable between machines.
                var manifest = new StringBuilder();
                var seenPaths = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);
                foreach (string candidatePath in binaryPaths)
                {
                    string fullPath = Path.GetFullPath(candidatePath);
                    if (!seenPaths.Add(fullPath))
                        continue;
                    string fileHash = HashPerformanceCaptureFile(fullPath);
                    if (!fileHash.StartsWith("sha256:", StringComparison.Ordinal))
                        return fileHash;
                    manifest.Append(Path.GetFileName(fullPath));
                    manifest.Append(':');
                    manifest.Append(fileHash);
                    manifest.Append('\n');
                }

                if (manifest.Length == 0)
                    return "unavailable:executable-bundle-empty";
                byte[] bundleHash = SHA256.HashData(
                    Encoding.UTF8.GetBytes(manifest.ToString()));
                return "sha256:" +
                    Convert.ToHexString(bundleHash).ToLowerInvariant();
            }
            catch (Exception exception) when (exception is
                IOException or
                UnauthorizedAccessException or
                ArgumentException or
                NotSupportedException or
                CryptographicException)
            {
                return "unavailable:executable-hash-failed";
            }
        }

        private static string HashPerformanceCaptureFile(string path)
        {
            using var stream = new FileStream(
                Path.GetFullPath(path),
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read | FileShare.Delete,
                64 * 1024,
                FileOptions.SequentialScan);
            byte[] hash = SHA256.HashData(stream);
            return "sha256:" + Convert.ToHexString(hash).ToLowerInvariant();
        }

        internal static string ResolvePerformanceCaptureDirtyWorktreeState(
            string? explicitState = null,
            string? searchStartDirectory = null)
        {
            string? supplied = string.IsNullOrWhiteSpace(explicitState)
                ? Environment.GetEnvironmentVariable("NJULF_DIRTY_WORKTREE_STATE")
                : explicitState;
            if (!string.IsNullOrWhiteSpace(supplied))
            {
                string normalized = supplied.Trim().ToLowerInvariant();
                if (normalized is "clean" or "dirty")
                    return normalized;
                return "unavailable:invalid-dirty-worktree-state";
            }

            string start = string.IsNullOrWhiteSpace(searchStartDirectory)
                ? Environment.CurrentDirectory
                : searchStartDirectory;
            string? repositoryRoot = FindCaptureGitRepositoryRoot(start) ??
                FindCaptureGitRepositoryRoot(AppContext.BaseDirectory);
            if (repositoryRoot == null)
                return "unavailable:git-worktree-not-found";

            try
            {
                var startInfo = new ProcessStartInfo
                {
                    FileName = "git",
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    CreateNoWindow = true
                };
                startInfo.ArgumentList.Add("-C");
                startInfo.ArgumentList.Add(repositoryRoot);
                startInfo.ArgumentList.Add("status");
                startInfo.ArgumentList.Add("--porcelain=v1");
                startInfo.ArgumentList.Add("--untracked-files=normal");
                using Process? process = Process.Start(startInfo);
                if (process == null)
                    return "unavailable:git-status-start-failed";

                var outputTask = process.StandardOutput.ReadToEndAsync();
                var errorTask = process.StandardError.ReadToEndAsync();
                if (!process.WaitForExit(2_000))
                {
                    try
                    {
                        process.Kill(entireProcessTree: true);
                    }
                    catch (InvalidOperationException)
                    {
                    }
                    return "unavailable:git-status-timeout";
                }

                string output = outputTask.GetAwaiter().GetResult();
                _ = errorTask.GetAwaiter().GetResult();
                return process.ExitCode == 0
                    ? string.IsNullOrWhiteSpace(output) ? "clean" : "dirty"
                    : "unavailable:git-status-failed";
            }
            catch (Exception exception) when (exception is
                InvalidOperationException or
                System.ComponentModel.Win32Exception or
                IOException or
                UnauthorizedAccessException)
            {
                return "unavailable:git-status-failed";
            }
        }

        private static string? FindCaptureGitRepositoryRoot(string? startDirectory)
        {
            if (string.IsNullOrWhiteSpace(startDirectory))
                return null;

            DirectoryInfo? directory;
            try
            {
                directory = new DirectoryInfo(Path.GetFullPath(startDirectory));
            }
            catch (Exception exception) when (exception is
                ArgumentException or
                NotSupportedException or
                IOException or
                UnauthorizedAccessException)
            {
                return null;
            }

            for (int depth = 0; directory != null && depth < 64; depth++)
            {
                string gitPath = Path.Combine(directory.FullName, ".git");
                if (Directory.Exists(gitPath) || File.Exists(gitPath))
                    return directory.FullName;
                directory = directory.Parent;
            }

            return null;
        }

        internal static string ResolvePerformanceCaptureShaderBundleHash()
        {
            try
            {
                Assembly assembly = typeof(ShaderLibrary).Assembly;
                string[] resourceNames = assembly.GetManifestResourceNames();
                Array.Sort(resourceNames, StringComparer.Ordinal);

                const string resourcePrefix = "Njulf.Shaders.";
                using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
                AppendCaptureHashText(hash, "njulf-effective-shader-bundle-v1");

                int shaderResourceCount = 0;
                foreach (string resourceName in resourceNames)
                {
                    if (!resourceName.StartsWith(resourcePrefix, StringComparison.Ordinal))
                        continue;

                    string shaderFileName = resourceName[resourcePrefix.Length..];
                    using Stream? stream = OpenEffectiveCaptureShaderStream(assembly, resourceName, shaderFileName);
                    if (stream == null)
                        return "unavailable:shader-resource-missing";

                    AppendCaptureHashText(hash, shaderFileName);
                    AppendCaptureHashStream(hash, stream);
                    shaderResourceCount++;
                }

                if (shaderResourceCount == 0)
                    return "unavailable:shader-resources-not-embedded";

                return "sha256:" + Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant();
            }
            catch (IOException)
            {
                return "unavailable:shader-bundle-hash-failed";
            }
            catch (UnauthorizedAccessException)
            {
                return "unavailable:shader-bundle-hash-failed";
            }
            catch (NotSupportedException)
            {
                // Capture export must remain available even in a stripped or damaged deployment.
                // The reason makes the missing identity explicit instead of silently emitting a
                // generic placeholder.
                return "unavailable:shader-bundle-hash-failed";
            }
            catch (CryptographicException)
            {
                return "unavailable:shader-bundle-hash-failed";
            }
        }

