        private sealed record AsyncComputePlan(
            AsyncComputeMode RequestedMode,
            AsyncComputeMode EffectiveMode,
            bool Supported,
            AsyncComputeSubmissionPlan SubmissionPlan,
            RenderGraphDiagnostics GraphDiagnostics,
            string Status)
        {
            public bool Requested => RequestedMode != AsyncComputeMode.Disabled;
            public bool Enabled => SubmissionPlan.ContainsAsyncCompute;
            public IReadOnlyList<string> CandidatePasses => SubmissionPlan.Paths
                .Where(path => path.Requested &&
                               path.Supported &&
                               path.Status is not AsyncComputePathStatus.MissingResourcePlan and not AsyncComputePathStatus.ValidationFallback)
                .SelectMany(path => path.Passes)
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            public IReadOnlyList<string> EnabledPasses => SubmissionPlan.ActivePasses;
            public int QueueOwnershipTransitionCount => SubmissionPlan.QueueFamilyOwnershipTransferCount;
        }

        private UploadBudgetSnapshot BuildUploadBudgetSnapshot(SceneRenderingData sceneData, RenderBudgetProfile profile)
        {
            _uploadBudgetTracker.BeginFrame();
            _uploadBudgetTracker.AddBytes(
                UploadBudgetCategory.Scene,
                sceneData.ObjectUploadBytes +
                sceneData.InstanceUploadBytes +
                sceneData.MeshletDrawUploadBytes +
                sceneData.SolidDepthMeshletDrawUploadBytes +
                sceneData.MaskedDepthMeshletDrawUploadBytes +
                sceneData.TransparentMeshletDrawUploadBytes);
            _uploadBudgetTracker.AddBytes(
                UploadBudgetCategory.Materials,
                sceneData.MaterialUploadBytes + sceneData.MaterialExtensionUploadBytes);
            _uploadBudgetTracker.AddBytes(UploadBudgetCategory.Lights, sceneData.LightUploadBytes);
            _uploadBudgetTracker.AddBytes(UploadBudgetCategory.Animation, sceneData.SkinningUploadBytes);
            _uploadBudgetTracker.AddBytes(
                UploadBudgetCategory.Particles,
                sceneData.ParticleInstanceUploadBytes + sceneData.TrailBeamUploadBytes);
            _uploadBudgetTracker.AddBytes(UploadBudgetCategory.Reflections, (ulong)Math.Max(0, sceneData.ReflectionProbeCount) * 0UL);
            ulong knownBytes =
                sceneData.ObjectUploadBytes +
                sceneData.InstanceUploadBytes +
                sceneData.MeshletDrawUploadBytes +
                sceneData.SolidDepthMeshletDrawUploadBytes +
                sceneData.MaskedDepthMeshletDrawUploadBytes +
                sceneData.TransparentMeshletDrawUploadBytes +
                sceneData.MaterialUploadBytes +
                sceneData.MaterialExtensionUploadBytes +
                sceneData.LightUploadBytes +
                sceneData.SkinningUploadBytes +
                sceneData.ParticleInstanceUploadBytes +
                sceneData.TrailBeamUploadBytes;
            if (sceneData.UploadedBytes > knownBytes)
                _uploadBudgetTracker.AddBytes(UploadBudgetCategory.Unknown, sceneData.UploadedBytes - knownBytes);

            return _uploadBudgetTracker.EndFrame(profile);
        }

        private MemoryBudgetSnapshot BuildMemoryBudgetSnapshot(RenderBudgetProfile profile)
        {
            MemoryBudgetSnapshot tracked = _bufferManager.AllocationTracker.CreateSnapshot(profile);
            var entries = new List<MemoryBudgetEntry>(tracked.Entries.Count + 8);
            ulong totalBytes = 0;
            foreach (MemoryBudgetEntry entry in tracked.Entries)
                AddMemoryEntry(entries, ref totalBytes, entry.Category, entry.Bytes, entry.AllocationCount, entry.Description);

            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.TextureAssets,
                _textureManager.FileTextureBytes + _textureManager.DefaultTextureBytes,
                _textureManager.TextureCount,
                "Texture assets");
            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.RenderTargets,
                _renderTargets?.TotalEstimatedBytes ?? 0,
                _renderTargets?.RenderTargetCount ?? 0,
                "Renderer-owned render targets");
            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.ShadowMaps,
                (_directionalShadowResources?.EstimatedImageBytes ?? 0) +
                (_spotShadowAtlas?.EstimatedImageBytes ?? 0) +
                (_pointShadowCubemapArray?.EstimatedImageBytes ?? 0),
                3,
                "Shadow map images");
            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.EnvironmentMaps,
                _environmentManager?.EstimatedBytes ?? 0,
                _environmentManager?.TextureResourceCount ?? 0,
                "Environment maps and BRDF LUT");
            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.ReflectionProbes,
                _reflectionProbeManager?.CubemapArrayBytes ?? 0,
                _reflectionProbeManager == null ? 0 : 1,
                "Reflection probe cubemap array");
            // DDGI, Simple-DDGI, far-field, and GI acceleration-structure allocations register
            // themselves with AllocationTracker under GlobalIllumination. Adding the managers'
            // counters again here double-counted the same residency. GI render targets are
            // already included in the renderer-owned render-target entry above; detailed unique
            // GI residency is assembled from these disjoint sources by GiResidencyReporter.
            AddMemoryEntry(
                entries,
                ref totalBytes,
                MemoryBudgetCategory.Swapchain,
                _swapchain.EstimatedBytes,
                (int)_swapchain.ImageCount + 1,
                "Swapchain color images and depth target");

            entries.Sort((left, right) => left.Category.CompareTo(right.Category));
            return new MemoryBudgetSnapshot(
                totalBytes,
                profile.GpuMemoryBudgetBytes,
                entries,
                _context.GetMemoryHeapBudgetSnapshot());
        }

        private static void AddMemoryEntry(
            List<MemoryBudgetEntry> entries,
            ref ulong totalBytes,
            MemoryBudgetCategory category,
            ulong bytes,
            int allocationCount,
            string description)
        {
            if (bytes == 0 && allocationCount == 0)
                return;

            for (int i = 0; i < entries.Count; i++)
            {
                MemoryBudgetEntry existing = entries[i];
                if (existing.Category == category)
                {
                    entries[i] = existing with
                    {
                        Bytes = existing.Bytes + bytes,
                        AllocationCount = existing.AllocationCount + allocationCount
                    };
                    totalBytes += bytes;
                    return;
                }
            }

            entries.Add(new MemoryBudgetEntry(category, bytes, allocationCount, description));
            totalBytes += bytes;
        }

        private static RenderBudgetStatus FindMetricStatus(RenderBudgetSnapshot snapshot, string metricName)
        {
            foreach (BudgetMetric metric in snapshot.Metrics)
            {
                if (string.Equals(metric.Name, metricName, StringComparison.Ordinal))
                    return metric.Status;
            }

            return RenderBudgetStatus.Unknown;
        }

        private static ulong GetMemoryCategoryBytes(MemoryBudgetSnapshot snapshot, MemoryBudgetCategory category)
        {
            foreach (MemoryBudgetEntry entry in snapshot.Entries)
            {
                if (entry.Category == category)
                    return entry.Bytes;
            }

            return 0;
        }

        private static long CalculateGpuFrameMicroseconds(SceneRenderingData sceneData)
        {
            return sceneData.GpuDepthPrePassMicroseconds +
                sceneData.GpuDirectionalShadowMicroseconds +
                sceneData.GpuDirectionalRayShadowMicroseconds +
                sceneData.GpuDirectionalShadowTemporalMicroseconds +
                sceneData.GpuDirectionalShadowSpatialMicroseconds +
                sceneData.GpuSpotShadowMicroseconds +
                sceneData.GpuPointShadowMicroseconds +
                sceneData.GpuHiZBuildMicroseconds +
                sceneData.GpuMotionVectorMicroseconds +
                sceneData.GpuAmbientOcclusionMicroseconds +
                sceneData.GpuAmbientOcclusionBlurMicroseconds +
                sceneData.GpuAccelerationStructureBlasMicroseconds +
                sceneData.GpuAccelerationStructureTlasMicroseconds +
                sceneData.GpuDdgiUpdateMicroseconds +
                sceneData.GpuGiCompositeMicroseconds +
                sceneData.GpuLightCullMicroseconds +
                sceneData.GpuForwardOpaqueMicroseconds +
                sceneData.GpuTransparentMicroseconds +
                sceneData.GpuParticleMicroseconds +
                sceneData.GpuTrailBeamMicroseconds +
                sceneData.GpuFogMicroseconds +
                sceneData.GpuAutoExposureMicroseconds +
                sceneData.GpuAntiAliasingMicroseconds +
                sceneData.GpuBloomExtractMicroseconds +
                sceneData.GpuBloomDownsampleMicroseconds +
                sceneData.GpuBloomUpsampleMicroseconds +
                sceneData.GpuCompositeMicroseconds +
                sceneData.GpuSkinningMicroseconds +
                sceneData.GpuReflectionProbeCaptureMicroseconds +
                sceneData.GpuReflectionProbePrefilterMicroseconds;
        }

        internal static GlobalIlluminationMode ResolveEffectiveGlobalIlluminationMode(
            GlobalIlluminationSettings settings,
            bool rayQuerySupported)
        {
            if (!settings.Enabled)
                return GlobalIlluminationMode.Disabled;
            return settings.Mode == GlobalIlluminationMode.Ddgi
                ? GlobalIlluminationMode.Ddgi
                : GlobalIlluminationMode.Disabled;
        }

        private string BuildGpuTimingReason()
        {
            if (!_gpuTimestamps.Supported)
                return _gpuTimestamps.UnsupportedReason;

            if (!Settings.Debug.AllowGpuTiming)
                return "GPU timing is disabled. Enable RenderSettings.Debug.AllowGpuTiming or press Ctrl+F4 in the sample.";

            if (_gpuTimestamps.PendingThisFrame && !HasCompletedGpuTiming(_gpuTimestamps.LastCompletedSnapshot))
                return "GPU timing is enabled; waiting for a completed frame of timestamp results.";

            return string.Empty;
        }

        private static bool HasCompletedGpuTiming(FrameTimingSnapshot timings)
        {
            foreach (PassTiming timing in timings.Passes)
            {
                if (timing.GpuAvailable)
                    return true;
            }

            return false;
        }

        private static bool HasCompletedDdgiGpuTiming(FrameTimingSnapshot timings)
        {
            return HasCompletedSimpleDdgiGpuTiming(timings);
        }

        private static bool HasCompletedSimpleDdgiGpuTiming(FrameTimingSnapshot timings)
        {
            return HasCompletedGpuTiming(timings, "SimpleDdgiPageDemandPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiPageResidencyPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiPageFeedbackPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiSchedulePass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiTracePass") ||
                HasCompletedGpuTiming(
                    timings,
                    "SimpleDdgiDirectionalRadiancePass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiAcceleratedSolvePass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiTransportPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiBlendPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiPublishPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiTransportAuditPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiRelocateClassifyPass") ||
                HasCompletedGpuTiming(timings, "SimpleDdgiSchedulerCommitPass");
        }

        private static bool HasCompletedGpuTiming(FrameTimingSnapshot timings, string passName)
        {
            return timings.TryGetPass(passName, out PassTiming timing) && timing.GpuAvailable;
        }

        private static void ApplyCompletedGpuTimings(SceneRenderingData sceneData, FrameTimingSnapshot timings)
        {
            sceneData.GpuSkinningMicroseconds = timings.GetGpuMicrosecondsOrZero("SkinningPass");
            sceneData.GpuDirectionalShadowMicroseconds = timings.GetGpuMicrosecondsOrZero("DirectionalShadowPass");
            sceneData.GpuDirectionalRayShadowMicroseconds =
                timings.GetGpuMicrosecondsOrZero("DirectionalRayShadowPass");
            sceneData.GpuDirectionalShadowTemporalMicroseconds =
                timings.GetGpuMicrosecondsOrZero("DirectionalShadowTemporalPass");
            sceneData.GpuDirectionalShadowSpatialMicroseconds =
                timings.GetGpuMicrosecondsOrZero("DirectionalShadowSpatialPass");
            sceneData.GpuSpotShadowMicroseconds = timings.GetGpuMicrosecondsOrZero("SpotShadowPass");
            sceneData.GpuPointShadowMicroseconds = timings.GetGpuMicrosecondsOrZero("PointShadowPass");
            sceneData.GpuReflectionProbeCaptureMicroseconds =
                timings.GetGpuMicrosecondsOrZero("ReflectionProbeCapturePass");
            sceneData.GpuReflectionProbePrefilterMicroseconds =
                timings.GetGpuMicrosecondsOrZero("ReflectionProbePrefilterPass");
            sceneData.GpuDepthPrePassMicroseconds = timings.GetGpuMicrosecondsOrZero("DepthPrePass");
            sceneData.GpuMotionVectorMicroseconds = timings.GetGpuMicrosecondsOrZero("MotionVectorPass");
            sceneData.GpuHiZBuildMicroseconds = timings.GetGpuMicrosecondsOrZero("HiZBuildPass");
            sceneData.GpuAmbientOcclusionMicroseconds = timings.GetGpuMicrosecondsOrZero("AmbientOcclusionPass");
            sceneData.GpuAmbientOcclusionBlurMicroseconds = timings.GetGpuMicrosecondsOrZero("AmbientOcclusionBlurPass");
            sceneData.GpuOpacityMicromapBuildMicroseconds =
                timings.GetGpuMicrosecondsOrZero(
                    "OpacityMicromapBuildPass");
            sceneData.GpuAccelerationStructureBlasMicroseconds = checked(
                timings.GetGpuMicrosecondsOrZero(
                    "AccelerationStructureBlasPass") +
                sceneData.GpuOpacityMicromapBuildMicroseconds);
            sceneData.GpuAccelerationStructureTlasMicroseconds = timings.GetGpuMicrosecondsOrZero("AccelerationStructureTlasPass");
            sceneData.GpuDdgiFoliageProxyGenerationMicroseconds =
                timings.GetGpuMicrosecondsOrZero(
                    "DdgiFoliageProxyGenerationPass");
            sceneData.GpuSimpleDdgiPageDemandMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiPageDemandPass");
            sceneData.GpuSimpleDdgiPageResidencyMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiPageResidencyPass");
            sceneData.GpuSimpleDdgiPageFeedbackMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiPageFeedbackPass");
            sceneData.GpuSimpleDdgiScheduleMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedulePass");
            sceneData.GpuSimpleDdgiScheduleResetMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Reset");
            sceneData.GpuSimpleDdgiScheduleClassifyMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Classify");
            sceneData.GpuSimpleDdgiSchedulePrefixMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Prefix");
            sceneData.GpuSimpleDdgiScheduleLaneBaseMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.LaneBase");
            sceneData.GpuSimpleDdgiScheduleCompactMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Compact");
            sceneData.GpuSimpleDdgiScheduleTailAdmitMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.TailAdmit");
            sceneData.GpuSimpleDdgiScheduleAdmitMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Admit");
            sceneData.GpuSimpleDdgiScheduleMaterializeMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Materialize");
            sceneData.GpuSimpleDdgiScheduleEmitMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedule.Emit");
            sceneData.GpuSimpleDdgiTraceMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiTracePass");
            sceneData.GpuSimpleDdgiDirectionalRadianceMicroseconds =
                timings.GetGpuMicrosecondsOrZero(
                    "SimpleDdgiDirectionalRadiancePass");
            sceneData.GpuSimpleDdgiAcceleratedSolveMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiAcceleratedSolvePass");
            sceneData.GpuSimpleDdgiTransportMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiTransportPass");
            sceneData.GpuSimpleDdgiBlendMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiBlendPass");
            sceneData.GpuSimpleDdgiRelocateClassifyMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiRelocateClassifyPass");
            sceneData.GpuSimpleDdgiPublishMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiPublishPass");
            sceneData.GpuSimpleDdgiTransportAuditMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiTransportAuditPass");
            sceneData.GpuSimpleDdgiCommitMicroseconds = timings.GetGpuMicrosecondsOrZero("SimpleDdgiSchedulerCommitPass");
            sceneData.GpuSimpleDdgiUrgentRelightMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiUrgentRelightPass");
            sceneData.GpuFarFieldUpdateMicroseconds = timings.GetGpuMicrosecondsOrZero("FarFieldClipmapBakePass");
            sceneData.GpuFarFieldUpdateTimingValid = HasCompletedGpuTiming(timings, "FarFieldClipmapBakePass") ? 1 : 0;
            sceneData.GpuDdgiUpdateMicroseconds =
                sceneData.GpuDdgiFoliageProxyGenerationMicroseconds +
                sceneData.GpuSimpleDdgiPageDemandMicroseconds +
                sceneData.GpuSimpleDdgiPageResidencyMicroseconds +
                sceneData.GpuSimpleDdgiPageFeedbackMicroseconds +
                sceneData.GpuSimpleDdgiScheduleMicroseconds +
                sceneData.GpuSimpleDdgiTraceMicroseconds +
                sceneData.GpuSimpleDdgiDirectionalRadianceMicroseconds +
                sceneData.GpuSimpleDdgiAcceleratedSolveMicroseconds +
                sceneData.GpuSimpleDdgiTransportMicroseconds +
                sceneData.GpuSimpleDdgiBlendMicroseconds +
                sceneData.GpuSimpleDdgiTransportAuditMicroseconds +
                sceneData.GpuSimpleDdgiRelocateClassifyMicroseconds +
                sceneData.GpuSimpleDdgiPublishMicroseconds +
                sceneData.GpuSimpleDdgiCommitMicroseconds;
            sceneData.GpuGiCompositeMicroseconds = 0;
            sceneData.GpuLightCullMicroseconds = timings.GetGpuMicrosecondsOrZero("TiledLightCullingPass");
            sceneData.GpuFoliageCullMicroseconds = timings.GetGpuMicrosecondsOrZero("FoliageCullPass");
            sceneData.GpuFoliageShadowMicroseconds = sceneData.FoliageCastShadows && sceneData.FoliageClusterCount > 0
                ? sceneData.GpuDirectionalShadowMicroseconds
                : 0;
            sceneData.GpuForwardOpaqueMicroseconds = timings.GetGpuMicrosecondsOrZero("ForwardPlusPass");
            sceneData.GpuForwardGiGatherMicroseconds = timings.GetGpuMicrosecondsOrZero("ForwardGiGatherPass");
            sceneData.GpuSimpleDdgiReceiverCacheMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiReceiverCachePass");
            sceneData.GpuForwardGiGatherTimingCoverage = HasCompletedGpuTiming(timings, "ForwardGiGatherPass") ? 1 : 0;
            sceneData.GpuTransparentMicroseconds =
                timings.GetGpuMicrosecondsOrZero("TransparentForwardPass") +
                timings.GetGpuMicrosecondsOrZero("WeightedTransparentPass") +
                timings.GetGpuMicrosecondsOrZero("WeightedOitCompositePass");
            sceneData.GpuParticleMicroseconds =
                timings.GetGpuMicrosecondsOrZero("GpuParticleResetPass") +
                timings.GetGpuMicrosecondsOrZero("GpuParticleSimulatePass") +
                timings.GetGpuMicrosecondsOrZero("GpuParticleSortPass") +
                timings.GetGpuMicrosecondsOrZero("ParticlePass");
            sceneData.GpuDebugDrawMicroseconds = timings.GetGpuMicrosecondsOrZero("DebugDrawPass");
            sceneData.GpuDebugDdgiProbeMicroseconds =
                timings.GetGpuMicrosecondsOrZero("SimpleDdgiProbeDebugPass");
            sceneData.GpuDebugLightTileMicroseconds =
                timings.GetGpuMicrosecondsOrZero("DebugOverlayPass");
            sceneData.GpuDebugOverlayMicroseconds =
                sceneData.GpuDebugDdgiProbeMicroseconds +
                sceneData.GpuDebugLightTileMicroseconds;
            sceneData.GpuFogMicroseconds = timings.GetGpuMicrosecondsOrZero("FogPass");
            sceneData.GpuAutoExposureMicroseconds = timings.GetGpuMicrosecondsOrZero("AutoExposurePass");
            sceneData.GpuCompositeMicroseconds = timings.GetGpuMicrosecondsOrZero("ToneMapCompositePass");
            sceneData.GpuAntiAliasingMicroseconds = timings.GetGpuMicrosecondsOrZero("AntiAliasingPass");

            long bloom = timings.GetGpuMicrosecondsOrZero("BloomPass");
            if (bloom > 0)
            {
                sceneData.GpuBloomExtractMicroseconds = bloom;
                sceneData.GpuBloomDownsampleMicroseconds = 0;
                sceneData.GpuBloomUpsampleMicroseconds = 0;
            }
        }

        private static long EstimateAsyncComputeQueueBusyMicroseconds(
            AsyncComputeSubmissionPlan plan,
            FrameTimingSnapshot timings)
        {
            if (plan == null || !plan.ContainsAsyncCompute)
                return 0;

            long total = 0;
            foreach (AsyncComputeSubmissionSegment segment in plan.Segments)
            {
                if (segment.Queue != AsyncComputeQueue.Compute)
                    continue;
                foreach (string pass in segment.Passes)
                    total = checked(total + timings.GetGpuMicrosecondsOrZero(pass));
            }

            return total;
        }

        /// <summary>
        /// Timestamp query pools provide pass durations rather than queue-global wall-clock
        /// intervals, so overlap is intentionally an estimate. For each compute segment we use
        /// the immediately following graphics segment as its useful overlap window. This remains
        /// meaningful for diagnostics and Auto policy without claiming an unmeasured queue span.
        /// </summary>
        private static long EstimateAsyncComputeOverlapMicroseconds(
            AsyncComputeSubmissionPlan plan,
            FrameTimingSnapshot timings)
        {
            if (plan == null || !plan.ContainsAsyncCompute)
                return 0;

            long totalOverlap = 0;
            for (int segmentIndex = 0; segmentIndex < plan.Segments.Count; segmentIndex++)
            {
                AsyncComputeSubmissionSegment compute = plan.Segments[segmentIndex];
                if (compute.Queue != AsyncComputeQueue.Compute)
                    continue;

                long computeBusy = SumGpuPassMicroseconds(compute.Passes, timings);
                long graphicsWindow = 0;
                for (int next = segmentIndex + 1; next < plan.Segments.Count; next++)
                {
                    AsyncComputeSubmissionSegment candidate = plan.Segments[next];
                    if (candidate.Queue != AsyncComputeQueue.Graphics)
                        continue;
                    graphicsWindow = SumGpuPassMicroseconds(candidate.Passes, timings);
                    break;
                }

                totalOverlap = checked(totalOverlap + Math.Min(computeBusy, graphicsWindow));
            }

            return Math.Max(0, totalOverlap);
        }

        private static long EstimateAsyncComputeFirstConsumerWaitMicroseconds(
            AsyncComputeSubmissionPlan plan,
            FrameTimingSnapshot timings)
        {
            if (plan == null || !plan.ContainsAsyncCompute)
                return 0;

            long totalWait = 0;
            for (int segmentIndex = 0; segmentIndex < plan.Segments.Count; segmentIndex++)
            {
                AsyncComputeSubmissionSegment compute = plan.Segments[segmentIndex];
                if (compute.Queue != AsyncComputeQueue.Compute)
                    continue;

                long computeBusy = SumGpuPassMicroseconds(compute.Passes, timings);
                long graphicsWindow = 0;
                for (int next = segmentIndex + 1; next < plan.Segments.Count; next++)
                {
                    AsyncComputeSubmissionSegment candidate = plan.Segments[next];
                    if (candidate.Queue != AsyncComputeQueue.Graphics)
                        continue;
                    graphicsWindow = SumGpuPassMicroseconds(candidate.Passes, timings);
                    break;
                }

                totalWait = checked(totalWait + Math.Max(0, computeBusy - graphicsWindow));
            }

            return totalWait;
        }

        private static long SumGpuPassMicroseconds(
            IReadOnlyList<string> passNames,
            FrameTimingSnapshot timings)
        {
            long total = 0;
            foreach (string passName in passNames)
                total = checked(total + timings.GetGpuMicrosecondsOrZero(passName));
            return total;
        }

        private static bool ForwardOcclusionCountersReconcile(SceneRenderingData sceneData)
        {
            if (sceneData.SceneSubmissionGpuCompactionActive &&
                sceneData.SceneSubmissionFallbackReason.Length == 0 &&
                sceneData.ForwardOcclusionTestedMeshletsGpu > 0)
            {
                return sceneData.ForwardOcclusionCulledMeshletsGpu <= sceneData.ForwardOcclusionTestedMeshletsGpu;
            }

            if (sceneData.ForwardTaskInvocations <= 0)
                return true;

            if (!sceneData.OcclusionCullingEnabled || sceneData.HiZMipCount == 0)
                return sceneData.ForwardOcclusionTestedMeshletsGpu == 0 &&
                    sceneData.ForwardOcclusionCulledMeshletsGpu == 0;

            int visibleAfterFrustum = Math.Max(0, sceneData.ForwardTaskInvocations - sceneData.ForwardFrustumCulledMeshletsGpu);
            return sceneData.ForwardOcclusionTestedMeshletsGpu == visibleAfterFrustum &&
                sceneData.ForwardOcclusionCulledMeshletsGpu + sceneData.ForwardEmittedMeshletsGpu == sceneData.ForwardOcclusionTestedMeshletsGpu;
        }

        private static string BuildForwardOcclusionSanity(
            SceneRenderingData sceneData,
            bool gpuMeshletCountersEnabled,
            bool reconciled)
        {
            if (!gpuMeshletCountersEnabled)
                return "GPU meshlet counters disabled.";

            if (sceneData.SceneSubmissionGpuCompactionActive &&
                sceneData.SceneSubmissionFallbackReason.Length == 0 &&
                sceneData.ForwardOcclusionTestedMeshletsGpu > 0)
            {
                return reconciled
                    ? "Scene submission Hi-Z occlusion counters reconcile: rejected is within tested."
                    : "Scene submission Hi-Z occlusion counters do not reconcile.";
            }

            if (sceneData.ForwardTaskInvocations <= 0)
                return "No completed forward GPU counters are available yet.";

            if (!sceneData.OcclusionCullingEnabled || sceneData.HiZMipCount == 0)
            {
                return reconciled
                    ? "Hi-Z occlusion disabled; tested and rejected counters are zero."
                    : "Hi-Z occlusion disabled, but tested or rejected counters are non-zero.";
            }

            if (reconciled)
                return "Forward occlusion counters reconcile: emitted plus rejected equals tested.";

            return "Forward occlusion counters do not reconcile; inspect shader diagnostics and frame latency.";
        }

        private void PrepareReflectionProbes(Scene scene, SceneRenderingData sceneData)
        {
            if (_reflectionProbeManager == null)
                return;

            _reflectionProbeCompletionValues.SetFrameSerial(_ddgiFrameSerial);
            _reflectionProbeManager.BeginFrameResourceRetirement(
                _ddgiFrameSerial,
                _completedGraphicsFrameFenceValue);
            _reflectionProbeManager.PollCaptureCompletions(_ddgiFrameSerial);
            FrameTimingSnapshot completedReflectionTimings = _gpuTimestamps.LastCompletedSnapshot;
            _reflectionProbeManager.UpdateCaptureGpuTimingHistory(
                completedReflectionTimings.GetGpuMicrosecondsOrZero("ReflectionProbeCapturePass"),
                completedReflectionTimings.GetGpuMicrosecondsOrZero("ReflectionProbePrefilterPass"),
                completedReflectionTimings.GetGpuMicrosecondsOrZero("ReflectionProbePublishPass"));
            LightingVersionSnapshot lightingVersions = LightingVersions;
            _reflectionProbeManager.UpdateCaptureVersions(lightingVersions);
            _reflectionProbeManager.Upload(
                scene.ReflectionProbes,
                _stagingRing,
                _currentCommandBuffer,
                scene.ReflectionProbeRevision);
            // Upload may allocate or recreate the cubemap array. Register only when the
            // manager marks its descriptor dirty; this keeps the global environment bound as
            // the explicit fallback until a local array is available.
            _reflectionProbeManager.Register(_bindlessHeap);

            ReflectionSettings settings = Settings.Reflections;
            sceneData.ReflectionsEnabled = settings.Enabled && settings.Mode != ReflectionMode.Disabled;
            sceneData.ReflectionMode = settings.Mode;
            sceneData.ReflectionDebugView = settings.DebugView;
            sceneData.ReflectionProbeCount = _reflectionProbeManager.ActiveProbeCount;
            sceneData.ReflectionProbeCapacity = _reflectionProbeManager.ProbeCapacity;
            sceneData.MaxReflectionProbesPerPixel = settings.MaxProbesPerPixel;
            sceneData.ReflectionProbeResolution = _reflectionProbeManager.ProbeResolution;
            sceneData.ReflectionProbeMipCount = _reflectionProbeManager.ProbeMipCount;
            sceneData.ReflectionProbeEstimatedBytes = _reflectionProbeManager.EstimatedBytes;
            sceneData.ReflectionProbeCapturesQueued = _reflectionProbeManager.CapturesQueued;
            sceneData.ReflectionProbeCapturesCompleted = _reflectionProbeManager.CapturesCompleted;
            sceneData.CpuReflectionProbeUploadMicroseconds = _reflectionProbeManager.LastUploadMicroseconds;
        }

        private void RecordReflectionProbeWork(SceneRenderingData sceneData)
        {
            if (_reflectionProbeManager == null)
                return;

            if (_reflectionProbeCapturePass?.ShouldExecute(_currentFrame, sceneData) == true)
            {
                long start = Stopwatch.GetTimestamp();
                _gpuTimestamps.BeginPass(_currentCommandBuffer, _currentFrame, "ReflectionProbeCapturePass");
                try
                {
                    _reflectionProbeCapturePass.Execute(_currentCommandBuffer, _currentFrame, sceneData);
                }
                finally
                {
                    _gpuTimestamps.EndPass(_currentCommandBuffer, _currentFrame);
                    sceneData.CpuReflectionProbeCaptureRecordMicroseconds += ElapsedMicroseconds(start);
                }
            }

            if (_reflectionProbePrefilterPass?.ShouldExecute(_currentFrame, sceneData) == true)
            {
                long start = Stopwatch.GetTimestamp();
                _gpuTimestamps.BeginPass(_currentCommandBuffer, _currentFrame, "ReflectionProbePrefilterPass");
                try
                {
                    _reflectionProbePrefilterPass.Execute(_currentCommandBuffer, _currentFrame, sceneData);
                }
                finally
                {
                    _gpuTimestamps.EndPass(_currentCommandBuffer, _currentFrame);
                    sceneData.CpuReflectionProbePrefilterRecordMicroseconds += ElapsedMicroseconds(start);
                }
            }

            if (_reflectionProbePublishPass?.ShouldExecute(_currentFrame, sceneData) == true)
            {
                _gpuTimestamps.BeginPass(_currentCommandBuffer, _currentFrame, "ReflectionProbePublishPass");
                try
                {
                    _reflectionProbePublishPass.Execute(_currentCommandBuffer, _currentFrame, sceneData);
                }
                finally
                {
                    _gpuTimestamps.EndPass(_currentCommandBuffer, _currentFrame);
                }
            }
        }

        private void FinalizeSimpleDdgiReceiverFeedbackCapture()
        {
            SimpleDdgiReceiverFeedbackVulkanRuntime? runtime =
                _simpleDdgiReceiverFeedbackRuntime;
            if (runtime is null || !runtime.HasPendingOwnedCapture(_currentFrame))
                return;

            // Refinement/base-fallback ownership is identified inside the live
            // gathers of every earlier receiver producer. Close that shared
            // class only here, after opaque, layered, transparent, particle,
            // fog, and reflection-capture work have all recorded their writes.
            if (runtime.IsPendingOwnedProducerRequired(
                    _currentFrame,
                    SimpleDdgiReceiverFeedbackProducer
                        .RefinementOrBaseFallback) &&
                !runtime.TryRecordOwnedProducerCompletion(
                    _currentCommandBuffer,
                    _currentFrame,
                    SimpleDdgiReceiverFeedbackProducer
                        .RefinementOrBaseFallback,
                    out string refinementCompletionReason))
            {
                runtime.AbortCapture(
                    "receiver-feedback-refinement-completion-failed:" +
                    refinementCompletionReason);
                return;
            }

            if (!runtime.TryRecordPendingOwnedReduction(
                    _currentCommandBuffer,
                    _currentFrame,
                    _gpuTimestamps,
                    out string reason))
            {
                runtime.AbortCapture(string.IsNullOrWhiteSpace(reason)
                    ? "receiver-feedback-late-frame-reduction-rejected"
                    : reason);
            }
        }

        private bool IncludeAsyncComputePass(string passName) =>
            _asyncComputePassNameScratch.Contains(passName);

        private void PrepareDdgiProbeVolumes(
            Scene scene,
            ICamera camera,
            SceneRenderingData sceneData,
            LightFrameSnapshot lightSnapshot,
            bool cameraCut)
        {
            bool simpleDdgiActive =
                Settings.GlobalIllumination.EffectiveUseDdgi &&
                _simpleDdgiVolumeManager != null &&
                _farFieldClipmapManager != null;
            bool simpleDdgiRayUpdateActive =
                simpleDdgiActive &&
                Settings.GlobalIllumination.EffectiveUseRayQueryBackend &&
                _context.RayQuerySupported &&
                _accelerationStructureManager?.Active == true;

            if (!simpleDdgiActive)
            {
                _ddgiMutationJournal.DetachScene();
                _ddgiMutationOraclePrimed = false;
                _simpleDdgiLivenessWatchdog.Reset();
                _simpleDdgiVolumeManager?.SetReceiverFeedbackSchedulingBinding(
                    SimpleDdgiReceiverFeedbackGpuSchedulingBinding.Disabled(
                        "receiver-feedback-simple-ddgi-disabled"),
                    sceneData.DdgiFrameSerial);
                _simpleDdgiVolumeManager?
                    .SetPublishedDirectionalGuidingSourceCache(0u, 0);
                _simpleDdgiVolumeManager?.EnsureDisabled(_stagingRing, _currentCommandBuffer);
                ResetDdgiDynamicTracking();
                UploadDdgiEmissiveSources(scene, sceneData, ddgiRayUpdateActive: false);
                _simpleDdgiGuidingFrameConfiguration =
                    SimpleDdgiGuidingFrameConfiguration.Disabled;
                _simpleDdgiGuidingConfigurationReason =
                    "directional-guiding-simple-ddgi-disabled";
                ReconcileSimpleDdgiReceiverFeedback(
                    simpleDdgiActive: false);
                ScheduleReflectionProbeRecapturesFromGi(sceneData, simpleDdgiActive: false);
                return;
            }

            // Simple DDGI owns its own camera-relative rings.  Only the scene-change
            // regions are shared with the scheduler, so the retired full-DDGI
            // clipmap layout is no longer built or uploaded.
            IReadOnlyList<DdgiDirtyRegion> dirtyRegions;
            if (Settings.GlobalIllumination.SimpleDdgiMutationJournalEnabled)
            {
                dirtyRegions = CollectDdgiDirtyRegionsFromJournal(
                    scene,
                    lightSnapshot,
                    sceneData);
            }
            else
            {
                _ddgiMutationJournal.DetachScene();
                _ddgiMutationOraclePrimed = false;
                dirtyRegions = CollectDdgiDirtyRegions(
                    scene,
                    lightSnapshot,
                    sceneData);
            }
            dirtyRegions = MergeDdgiFoliageProxyDirtyRegion(dirtyRegions);
            dirtyRegions = MergeDdgiSkinnedPoseDirtyRegions(
                scene,
                dirtyRegions);

            UploadDdgiEmissiveSources(scene, sceneData, simpleDdgiRayUpdateActive);

            _farFieldClipmapManager!.Upload(
                scene,
                camera.Position,
                _stagingRing,
                _currentCommandBuffer,
                sceneData.SceneContentRevision);
            sceneData.FarFieldPagedMode = _farFieldClipmapManager.PagedMode ? 1 : 0;
            sceneData.FarFieldPagePoolCapacity = _farFieldClipmapManager.PagePoolCapacity;
            sceneData.FarFieldResidentPageCount = _farFieldClipmapManager.ResidentPageCount;
            sceneData.FarFieldPendingPageCount = _farFieldClipmapManager.PendingPageCount;
            sceneData.FarFieldPageRequestCount = _farFieldClipmapManager.PageRequestCount;
            sceneData.FarFieldPageMissCount = _farFieldClipmapManager.PageMissCount;
            sceneData.FarFieldPageRebuildCount = _farFieldClipmapManager.PageRebuildCount;
            sceneData.FarFieldPageEvictionCount = _farFieldClipmapManager.PageEvictionsThisFrame;
            sceneData.FarFieldScheduledPageBakeCount = _farFieldClipmapManager.ScheduledPageBakeCount;
            sceneData.FarFieldCacheBytes = _farFieldClipmapManager.PageCacheBytes;
            sceneData.FarFieldMemoryBudgetBytes = Settings.GlobalIllumination.FarFieldMemoryBudgetBytes;
            sceneData.FarFieldInstanceBufferBytes = _farFieldClipmapManager.InstanceBufferBytes;
            sceneData.FarFieldPageTableBytes = _farFieldClipmapManager.PageTableBufferBytes;

            bool farFieldCoverageAvailable = _farFieldClipmapManager.CoverageReady;
            bool structuredGatherAvailable =
                simpleDdgiRayUpdateActive &&
                Settings.GlobalIllumination.SimpleDdgiStructuredGatherEnabled;
            SimpleDdgiDirtySignature dirtySignature = CreateSimpleDdgiDirtySignature(
                scene,
                lightSnapshot,
                _ddgiEmissiveSourceRevision);
            SimpleDdgiWarmStartSceneIdentity? warmStartIdentity =
                ResolveSimpleDdgiWarmStartSceneIdentity(
                    scene,
                    sceneData,
                    lightSnapshot);
            _simpleDdgiVolumeManager!.SetSchedulerCostEstimate(
                _simpleDdgiSchedulerCostModel.Estimate);
            IReadOnlyList<SimpleDdgiRefinementDemand> refinementEmissiveDemands =
                ResolveSimpleDdgiRefinementEmissiveDemands();

            // Reconcile B1 before the scheduler-frame upload. Frame N consumes
            // only frame N-1's immutable summary bank; the current frame's
            // receiver gather is recorded later by ForwardPlus and cannot
            // influence this scheduling decision.
            // C3 shares the same transient arena. Compile its desired state
            // before reconciliation as well so a live setting/prerequisite
            // disable publishes fallbacks and releases C3 in this transition,
            // rather than retaining the previous frame's arena request.
            _simpleDdgiGuidingFrameConfiguration =
                CompileSimpleDdgiGuidingFrameConfiguration(
                    simpleDdgiActive,
                    out _simpleDdgiGuidingConfigurationReason);
            ReconcileSimpleDdgiReceiverFeedback(simpleDdgiActive: true);
            SynchronizePublishedDirectionalGuidingSourceCache();
            SimpleDdgiReceiverFeedbackVulkanRuntime? receiverFeedbackRuntime =
                _simpleDdgiReceiverFeedbackRuntime;
            uint receiverFeedbackViewportGeneration =
                _renderTargets is { } currentReceiverFeedbackTargets
                    ? checked((uint)Math.Max(0,
                        currentReceiverFeedbackTargets.ResizeCount) + 1u)
                    : 0u;
            Vector3 receiverForward = camera.Forward.Normalized();
            if (receiverForward == Vector3.Zero)
                receiverForward = new Vector3(0f, 0f, -1f);
            float nearRingSpacing =
                SimpleDdgiVolumeManager.ResolveRingSpacing(
                    Settings.GlobalIllumination,
                    0);
            float visibleReceiverFocusDistance = Math.Max(
                1.5f,
                nearRingSpacing * 2f);
            Vector3 visibleReceiverFallbackFocus = camera.Position +
                receiverForward * visibleReceiverFocusDistance;
            Vector3? measuredReceiverFocus = null;
            if (receiverFeedbackRuntime is not null &&
                receiverFeedbackViewportGeneration != 0u &&
                receiverFeedbackRuntime.TryGetPublishedRefinementWitness(
                    receiverFeedbackViewportGeneration,
                    _simpleDdgiVolumeManager.VolumeTableGeneration,
                    sceneData.DdgiFrameSerial,
                    out SimpleDdgiReceiverFeedbackRefinementWitness
                        refinementWitness) &&
                _simpleDdgiVolumeManager.TryResolveBaseVolumeVirtualProbeWorldPosition(
                    refinementWitness.ResolvedVirtualProbeId,
                    out Vector3 resolvedMeasuredReceiverFocus))
            {
                measuredReceiverFocus = resolvedMeasuredReceiverFocus;
            }
            Vector3 visibleReceiverFocus =
                _simpleDdgiRefinementFocusTracker.Resolve(
                    visibleReceiverFallbackFocus,
                    camera.Position,
                    receiverForward,
                    Math.Max(0.5f, nearRingSpacing * 0.75f),
                    sceneData.CaptureCameraCutSerial,
                    sceneData.SceneContentRevision,
                    measuredReceiverFocus);
            SimpleDdgiReceiverFeedbackGpuSchedulingBinding receiverFeedbackBinding =
                receiverFeedbackRuntime is not null &&
                receiverFeedbackViewportGeneration != 0u
                    ? receiverFeedbackRuntime.AcquirePendingForGpuScheduling(
                        receiverFeedbackViewportGeneration,
                        sceneData.DdgiFrameSerial)
                    : SimpleDdgiReceiverFeedbackGpuSchedulingBinding.Disabled(
                        "receiver-feedback-runtime-or-render-targets-unavailable");
            if (receiverFeedbackBinding.UseFeedback &&
                !receiverFeedbackRuntime!.TryRecordSchedulingReadBarrier(
                    _currentCommandBuffer,
                    receiverFeedbackBinding,
                    out string receiverFeedbackBarrierReason))
            {
                receiverFeedbackBinding =
                    SimpleDdgiReceiverFeedbackGpuSchedulingBinding.Disabled(
                        receiverFeedbackBarrierReason);
            }
            _simpleDdgiVolumeManager.SetReceiverFeedbackSchedulingBinding(
                receiverFeedbackBinding,
                sceneData.DdgiFrameSerial);
            _simpleDdgiVolumeManager!.Upload(
                scene,
                camera.Position,
                _stagingRing,
                _currentCommandBuffer,
                _currentFrame,
                dirtySignature.Signature,
                dirtySignature.ReasonFlags,
                structuredGatherAvailable,
                farFieldCoverageAvailable,
                dirtyRegions,
                dirtySignature.CohortTransition,
                scene.GlobalIlluminationProbeVolumes,
                sceneData.SceneContentRevision,
                dirtySignature.SourceRefreshMode,
                dirtySignature.SourceRelightScale,
                warmStartIdentity,
                refinementEmissiveDemands,
                visibleReceiverFocus);

            _simpleDdgiGuidingFrameConfiguration =
                CompileSimpleDdgiGuidingFrameConfiguration(
                    simpleDdgiActive,
                    out _simpleDdgiGuidingConfigurationReason);
            // The first reconciliation happens before Upload so last frame's
            // immutable B1 summary can feed this frame's scheduling decision.
            // Upload establishes the initial physical probe domain, however,
            // so reconcile once more before any advanced-GI commands are
            // recorded. This makes ordinary explicit switches effective on
            // the first renderable frame instead of waiting for frame two.
            ReconcileSimpleDdgiReceiverFeedback(simpleDdgiActive: true);
            if (_simpleDdgiGuidingFrameConfiguration.IsEnabled &&
                _simpleDdgiGuidingFrameConfiguration.Equals(
                    _simpleDdgiGuidingAppliedArenaConfiguration))
            {
                SimpleDdgiGuidingFrameCoordinator? guidingCoordinator =
                    _simpleDdgiGuidingFrameCoordinator;
                if (guidingCoordinator is null)
                {
                    _simpleDdgiGuidingConfigurationReason =
                        "guiding-frame-coordinator-unavailable";
                }
                else if (!guidingCoordinator.TryConfigure(
                             _simpleDdgiGuidingFrameConfiguration,
                             _currentCommandBuffer,
                             out string guidingConfigureReason))
                {
                    _simpleDdgiGuidingConfigurationReason = guidingConfigureReason;
                }
                else if (!guidingCoordinator.TryPrepareFrame(
                        _currentFrame,
                        Math.Max(1UL, sceneData.DdgiFrameSerial),
                        _currentCommandBuffer,
                        out string guidingPrepareReason))
                {
                    _simpleDdgiGuidingConfigurationReason = guidingPrepareReason;
                }
            }

            sceneData.SimpleDdgiPageFullManagementRequired =
                _simpleDdgiVolumeManager.PrepareProbePageManagement(
                    camera.Position,
                    sceneData.ViewProjectionMatrix,
                    sceneData.SceneContentRevision,
                    sceneData.CaptureCameraCutSerial)
                    ? 1
                    : 0;

            PopulateSimpleDdgiFrameData(sceneData, simpleDdgiRayUpdateActive);
            sceneData.CpuDdgiRecordMicroseconds = 0;
            sceneData.CpuSimpleDdgiRecordMicroseconds = _simpleDdgiVolumeManager.LastUploadMicroseconds;
            sceneData.SimpleDdgiUploadTiming = _simpleDdgiVolumeManager.LastUploadTiming;
            sceneData.CpuFarFieldRecordMicroseconds = _farFieldClipmapManager.LastUploadMicroseconds;
            ScheduleReflectionProbeRecapturesFromGi(sceneData, simpleDdgiActive: true);
        }

        private SimpleDdgiGuidingFrameConfiguration
            CompileSimpleDdgiGuidingFrameConfiguration(
                bool simpleDdgiActive,
                out string reason)
        {
            SimpleDdgiVolumeManager? manager = _simpleDdgiVolumeManager;
            if (!simpleDdgiActive || !_advancedGiGraphModes.UsesDirectionalGuiding ||
                Settings.GlobalIllumination.SimpleDdgiDirectionalGuidingMode is not
                    (SimpleDdgiDirectionalGuidingMode.PerProbeHistogramExperiment or
                     SimpleDdgiDirectionalGuidingMode.AutoQualified) ||
                manager is null)
            {
                reason = "directional-guiding-disabled";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }

            if (Settings.GlobalIllumination
                    .SimpleDdgiDirectionalGuidingMode ==
                    SimpleDdgiDirectionalGuidingMode.AutoQualified &&
                !_advancedGiRuntimeContentState.Matched)
            {
                reason = _advancedGiRuntimeContentState.Reason;
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }

            AdvancedGiPrerequisiteGateResult gate =
                _advancedGiPrerequisiteManifest.Evaluate(
                    AdvancedGiPrerequisiteFeature.DirectionalGuiding);
            bool prerequisitesSatisfied =
                AdvancedGiActivationPolicy.PrerequisitesSatisfied(
                    Settings.GlobalIllumination
                        .SimpleDdgiDirectionalGuidingMode,
                    gate);
            if (!prerequisitesSatisfied)
            {
                reason = string.IsNullOrWhiteSpace(gate.FailureDetail)
                    ? "guiding-global-prerequisite-gate-rejected"
                    : gate.FailureDetail;
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }
            int totalPhysical = manager.PhysicalProbeCapacity;
            int directionSlots = manager.RaysPerProbe;
            if (totalPhysical <= 0 || directionSlots is <= 0 or >
                SimpleDdgiGuidingSourceCacheLayoutCompiler
                    .MaximumDirectionSlotsPerProbe)
            {
                reason = "guiding-ddgi-physical-or-ray-capacity-unavailable";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }

            GlobalIlluminationSettings gi = Settings.GlobalIllumination;
            int configuredUpdates = gi.SimpleDdgiProbeUpdatesPerFrame <= 0
                ? totalPhysical
                : Math.Min(totalPhysical, gi.SimpleDdgiProbeUpdatesPerFrame);
            int rayBudgetUpdates = gi.DdgiProbeUpdatePrimaryRayBudget <= 0
                ? 0
                : gi.DdgiProbeUpdatePrimaryRayBudget / directionSlots;
            int requestedScheduled = Math.Min(
                configuredUpdates,
                rayBudgetUpdates);
            if (requestedScheduled <= 0)
            {
                reason = "guiding-ddgi-frame-ray-budget-admits-no-probes";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }
            int compactTraceCapacity =
                manager.GuidingTraceDirectionScratchProbeCapacity;
            if (compactTraceCapacity <= 0)
            {
                reason = "guiding-compact-trace-payload-capacity-unavailable";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }

            // C3 settings are renderer-lifetime settings. Once its central
            // arena and persistent prefix have been admitted, their own live
            // allocations must not be charged against a later free-memory
            // snapshot and resized every frame. Reuse the allocation while it
            // remains a valid prefix of the current DDGI domain and workload.
            // A genuine layout or cardinality change still takes the normal
            // transactional reconciliation path below.
            SimpleDdgiGuidingFrameConfiguration applied =
                _simpleDdgiGuidingAppliedArenaConfiguration;
            if (IsCompatibleLiveSimpleDdgiGuidingConfiguration(
                    applied,
                    totalPhysical,
                    requestedScheduled,
                    compactTraceCapacity,
                    directionSlots,
                    manager.StoragePackingMode))
            {
                reason = "guiding-existing-renderer-lifetime-allocation-reused";
                return applied;
            }

            MemoryHeapBudgetSnapshot heapBudget =
                _context.GetMemoryHeapBudgetSnapshot();
            ulong memoryHeadroom = heapBudget.IsAvailable &&
                heapBudget.PrimaryBudgetBytes > heapBudget.PrimaryUsageBytes
                    ? heapBudget.PrimaryBudgetBytes - heapBudget.PrimaryUsageBytes
                    : 0UL;
            if (memoryHeadroom == 0UL)
            {
                reason = "guiding-device-memory-headroom-unavailable";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }

            int low = 1;
            // Compact payloads are addressed by stable physical probe, not by
            // the frame-local queue ordinal. This prevents a queue reorder
            // from inheriting another probe's direction/PDF transaction.
            int high = Math.Min(totalPhysical, compactTraceCapacity);
            SimpleDdgiGuidingFrameConfiguration best =
                SimpleDdgiGuidingFrameConfiguration.Disabled;
            while (low <= high)
            {
                int candidate = low + ((high - low) >> 1);
                if (TryCompileSimpleDdgiGuidingCandidate(
                        totalPhysical,
                        candidate,
                        Math.Min(requestedScheduled, candidate),
                        directionSlots,
                        memoryHeadroom,
                        prerequisitesSatisfied,
                        out SimpleDdgiGuidingFrameConfiguration compiled))
                {
                    best = compiled;
                    low = candidate + 1;
                }
                else
                {
                    high = candidate - 1;
                }
            }

            if (!best.IsEnabled)
            {
                reason = "guiding-16-mib-budget-admits-no-complete-layout";
                return SimpleDdgiGuidingFrameConfiguration.Disabled;
            }
            reason = best.RuntimeRequest.Layout.PhysicalProbeCapacity < totalPhysical
                ? "guiding-admitted-deterministic-physical-probe-prefix"
                : "guiding-full-physical-probe-domain-admitted";
            return best;
        }

        private static bool IsCompatibleLiveSimpleDdgiGuidingConfiguration(
            in SimpleDdgiGuidingFrameConfiguration configuration,
            int totalPhysicalProbeCapacity,
            int requestedScheduledProbeCapacity,
            int compactTraceProbeCapacity,
            int directionSlotsPerProbe,
            SimpleDdgiStoragePackingMode storagePackingMode)
        {
            if (!configuration.IsEnabled)
                return false;

            SimpleDdgiGuidingLayout layout =
                configuration.RuntimeRequest.Layout;
            SimpleDdgiGuidingSourceCacheLayout source =
                configuration.SourceCacheLayout;
            return layout.PhysicalProbeCapacity > 0 &&
                layout.PhysicalProbeCapacity <= totalPhysicalProbeCapacity &&
                layout.PhysicalProbeCapacity <= compactTraceProbeCapacity &&
                layout.ScheduledGuidedProbeCapacity > 0 &&
                layout.ScheduledGuidedProbeCapacity <=
                    requestedScheduledProbeCapacity &&
                layout.DirectionSlotsPerProbe == directionSlotsPerProbe &&
                source.AdmittedGuidedPhysicalProbeCapacity ==
                    layout.PhysicalProbeCapacity &&
                source.DirectionSlotsPerProbe == directionSlotsPerProbe &&
                configuration.RuntimeRequest.SourceStoragePackingMode ==
                    storagePackingMode;
        }

        private void SynchronizePublishedDirectionalGuidingSourceCache()
        {
            SimpleDdgiVolumeManager? manager = _simpleDdgiVolumeManager;
            SimpleDdgiGuidingSourceCacheSnapshot snapshot =
                _simpleDdgiGuidingSourceCacheSidecar?.Snapshot ??
                SimpleDdgiGuidingSourceCacheSnapshot.Disabled;
            if (manager is null)
                return;

            SimpleDdgiGuidingSourceCacheLayout layout = snapshot.Layout;
            if (!snapshot.IsReady || !snapshot.PayloadDescriptorPublished ||
                !layout.IsAdmitted ||
                layout.AdmittedGuidedPhysicalProbeCapacity <= 0 ||
                layout.DirectionSlotsPerProbe <= 0)
            {
                manager.SetPublishedDirectionalGuidingSourceCache(0u, 0);
                return;
            }

            manager.SetPublishedDirectionalGuidingSourceCache(
                checked((uint)layout.AdmittedGuidedPhysicalProbeCapacity),
                layout.DirectionSlotsPerProbe);
        }

        private bool TryCompileSimpleDdgiGuidingCandidate(
            int totalPhysicalProbeCapacity,
            int guidedPhysicalProbeCapacity,
            int scheduledGuidedProbeCapacity,
            int directionSlotsPerProbe,
            ulong memoryHeadroom,
            bool globalPrerequisiteGateAdmitted,
            out SimpleDdgiGuidingFrameConfiguration configuration)
        {
            configuration = SimpleDdgiGuidingFrameConfiguration.Disabled;
            try
            {
                var sidecar = SimpleDdgiGuidingSourceCacheLayoutCompiler.Compile(
                    new SimpleDdgiGuidingSourceCacheLayoutRequest(
                        Enabled: true,
                        TotalPhysicalProbeCapacity: totalPhysicalProbeCapacity,
                        RequestedGuidedPhysicalProbeCapacity:
                            guidedPhysicalProbeCapacity,
                        DirectionSlotsPerProbe: directionSlotsPerProbe,
                        MemoryBudgetBytes:
                            SimpleDdgiDirectionalGuidingExperimentBudgetBytes));
                if (!sidecar.IsAdmitted ||
                    sidecar.AdmittedGuidedPhysicalProbeCapacity !=
                        guidedPhysicalProbeCapacity)
                {
                    return false;
                }

                SimpleDdgiGuidingLayout layout =
                    SimpleDdgiGuidingLayoutCompiler.Compile(
                        new SimpleDdgiGuidingLayoutRequest(
                            SimpleDdgiGuidingDistributionConfiguration.EightByEight,
                            guidedPhysicalProbeCapacity,
                            scheduledGuidedProbeCapacity,
                            _context.MinimumStorageBufferOffsetAlignment,
                            AllocateValidationReferenceBank: false)
                        {
                            DirectionSlotsPerProbe = directionSlotsPerProbe,
                            DirectionPdfSidecarBudgetBytes =
                                SimpleDdgiDirectionalGuidingExperimentBudgetBytes
                        });
                ulong bankBytes = layout.PersistentDoubleBufferedBytes / 2UL;
                ulong maximumRange = _context.MaximumStorageBufferRange;
                if (!layout.TransientWorkspace.IsComplete ||
                    layout.TotalBytes >
                        SimpleDdgiDirectionalGuidingExperimentBudgetBytes ||
                    layout.TotalBytes > memoryHeadroom || bankBytes > maximumRange ||
                    layout.TransientWorkspace.TotalBytes > maximumRange ||
                    layout.DirectionPdfSidecarBytes > maximumRange)
                {
                    return false;
                }

                configuration = new SimpleDdgiGuidingFrameConfiguration(
                    new SimpleDdgiGuidingRuntimeRequest(true, layout)
                    {
                        SourceStoragePackingMode =
                            _simpleDdgiVolumeManager!.StoragePackingMode
                    },
                    sidecar,
                    globalPrerequisiteGateAdmitted,
                    SimpleDdgiGuidingProposalPolicy.ProductionBaseline);
                return true;
            }
            catch (Exception exception) when (exception is ArgumentException or
                OverflowException)
            {
                return false;
            }
        }

        private void ReconcileSimpleDdgiReceiverFeedback(bool simpleDdgiActive)
        {
            SimpleDdgiReceiverFeedbackVulkanRuntime? runtime =
                _simpleDdgiReceiverFeedbackRuntime;
            SimpleDdgiVolumeManager? manager = _simpleDdgiVolumeManager;
            RenderTargetManager? renderTargets = _renderTargets;
            if (runtime is null || manager is null || renderTargets is null)
                return;

            SimpleDdgiReceiverFeedbackMode requestedMode = simpleDdgiActive
                ? Settings.GlobalIllumination.SimpleDdgiReceiverFeedbackMode
                : SimpleDdgiReceiverFeedbackMode.Off;
            Extent2D extent = renderTargets.SceneColor.Extent;
            ulong screenTileCount = extent.Width == 0u || extent.Height == 0u
                ? 0UL
                : checked(
                    (((ulong)extent.Width +
                      ForwardPlusPass.SimpleDdgiReceiverGatherScale - 1UL) /
                     ForwardPlusPass.SimpleDdgiReceiverGatherScale) *
                    (((ulong)extent.Height +
                      ForwardPlusPass.SimpleDdgiReceiverGatherScale - 1UL) /
                     ForwardPlusPass.SimpleDdgiReceiverGatherScale));
            int physicalProbeCapacity = manager.PhysicalProbeCapacity;
            uint pageGeneration = Math.Max(
                1u,
                manager.ProbeResidencyResourceGeneration);
            AdvancedGiPrerequisiteGateResult gate =
                _advancedGiPrerequisiteManifest.Evaluate(
                    AdvancedGiPrerequisiteFeature.ReceiverFeedback);
            bool prerequisitesSatisfied =
                AdvancedGiActivationPolicy.PrerequisitesSatisfied(
                    requestedMode,
                    gate);
            AdvancedGiQualificationGateResult qualification =
                EvaluateAdvancedGiQualification(
                    AdvancedGiPrerequisiteFeature.ReceiverFeedback,
                    gate,
                    physicalProbeCapacity > 0,
                    Settings.GlobalIllumination
                        .SimpleDdgiReceiverFeedbackQualificationId);
            if (requestedMode ==
                    SimpleDdgiReceiverFeedbackMode.AutoQualified &&
                !_advancedGiRuntimeContentState.Matched)
            {
                qualification = AdvancedGiQualificationGateResult.Reject(
                    _advancedGiRuntimeContentState.Reason,
                    qualification.QualificationId);
            }
            MemoryHeapBudgetSnapshot heapBudget =
                _context.GetMemoryHeapBudgetSnapshot();
            ulong memoryHeadroom = heapBudget.IsAvailable &&
                heapBudget.PrimaryBudgetBytes > heapBudget.PrimaryUsageBytes
                    ? heapBudget.PrimaryBudgetBytes - heapBudget.PrimaryUsageBytes
                    : 0UL;
            ulong maximumStorageBufferRange =
                _context.MaximumStorageBufferRange;
            SimpleDdgiReceiverFeedbackProductionWorkload producerWorkload =
                CreateSimpleDdgiReceiverFeedbackProductionWorkload(
                    extent,
                    screenTileCount);

            var key = new SimpleDdgiReceiverFeedbackConfigurationKey(
                requestedMode,
                simpleDdgiActive,
                physicalProbeCapacity,
                producerWorkload,
                pageGeneration,
                maximumStorageBufferRange,
                prerequisitesSatisfied,
                gate.QualificationId,
                qualification.Passed,
                qualification.QualificationId,
                _advancedGiRuntimeContentState.Matched,
                memoryHeadroom >= SimpleDdgiReceiverFeedbackExperimentBudgetBytes);
            if (_simpleDdgiReceiverFeedbackConfigurationKey == key &&
                _simpleDdgiGuidingAppliedArenaConfiguration.Equals(
                    _simpleDdgiGuidingFrameConfiguration))
                return;

            SimpleDdgiReceiverFeedbackPlan plan =
                CompileSimpleDdgiReceiverFeedbackPlan(
                    requestedMode,
                    physicalProbeCapacity,
                    producerWorkload,
                    pageGeneration,
                    maximumStorageBufferRange,
                    memoryHeadroom,
                    gate,
                    qualification,
                    Settings.GlobalIllumination
                        .SimpleDdgiReceiverFeedbackQualificationId);
            AdvancedGiTransientBufferArena? transientArena =
                _advancedGiTransientBufferArena;
            SimpleDdgiGuidingFrameConfiguration guidingArenaConfiguration =
                _simpleDdgiGuidingFrameConfiguration;
            if (_simpleDdgiGuidingAppliedArenaConfiguration.IsEnabled)
            {
                // A B1 configuration change can resize the shared arena even
                // when C3's logical configuration is unchanged. Slot 202 and
                // the coordinator workspace would then name the retired arena
                // generation. Publish all C3 fallbacks and drain its frame
                // transactions before either owner can reconcile the arena.
                if (_simpleDdgiGuidingFrameCoordinator is null ||
                    !_simpleDdgiGuidingFrameCoordinator.TryConfigure(
                        SimpleDdgiGuidingFrameConfiguration.Disabled,
                        _currentCommandBuffer,
                        out _))
                {
                    // A C3 frame is still in flight. Keep the old arena and B1
                    // allocation unchanged; the requested transition will be
                    // retried after its owning frame fence.
                    return;
                }
            }

            string arenaFailure = "advanced-gi-transient-arena-is-unavailable";
            bool arenaReady = transientArena is not null &&
                TryReconcileAdvancedGiScratchArena(
                    transientArena,
                    plan,
                    guidingArenaConfiguration,
                    maximumStorageBufferRange,
                    memoryHeadroom,
                    out arenaFailure);
            if (!arenaReady && guidingArenaConfiguration.IsEnabled)
            {
                // C3 is independently optional. Preserve an otherwise valid
                // B1 transaction by retrying the central arena without C3.
                // Keep the original C3 rejection visible. The retry below can
                // succeed for B1 and overwrite arenaFailure with an unrelated
                // success detail, while the C3 runtime remains intentionally
                // untouched in its zero-resource state.
                _simpleDdgiGuidingConfigurationReason =
                    string.IsNullOrWhiteSpace(arenaFailure)
                        ? "directional-guiding-transient-arena-rejected"
                        : arenaFailure;
                guidingArenaConfiguration =
                    SimpleDdgiGuidingFrameConfiguration.Disabled;
                arenaReady = transientArena is not null &&
                    TryReconcileAdvancedGiScratchArena(
                        transientArena,
                        plan,
                        guidingArenaConfiguration,
                        maximumStorageBufferRange,
                        memoryHeadroom,
                        out arenaFailure);
            }
            if (!arenaReady)
                plan = RejectReceiverFeedbackForTransientArena(plan, arenaFailure);

            if (!runtime.TryConfigureOwned(
                    plan,
                    prerequisitesSatisfied,
                    out string runtimeFailure) && plan.UsesExactCompacted)
            {
                plan = RejectReceiverFeedbackForTransientArena(
                    plan,
                    string.IsNullOrWhiteSpace(runtimeFailure)
                        ? "receiver-feedback-owned-runtime-rejected"
                        : runtimeFailure);
                _ = runtime.TryConfigureOwned(
                    plan,
                    prerequisitesSatisfied,
                    out _);
            }
            _simpleDdgiReceiverFeedbackPlan = plan;
            _simpleDdgiReceiverFeedbackConfigurationKey = key;
            _simpleDdgiGuidingAppliedArenaConfiguration =
                guidingArenaConfiguration;
        }

        private bool TryReconcileAdvancedGiScratchArena(
            AdvancedGiTransientBufferArena arena,
            in SimpleDdgiReceiverFeedbackPlan plan,
            in SimpleDdgiGuidingFrameConfiguration guidingConfiguration,
            ulong maximumStorageBufferRange,
            ulong memoryHeadroom,
            out string failure)
        {
            ulong alignment = _context.MinimumStorageBufferOffsetAlignment;
            Span<GiExperimentScratchAllocation> requests =
                stackalloc GiExperimentScratchAllocation[2];
            int requestCount = 0;
            if (plan.UsesExactCompacted)
            {
                requests[requestCount++] = new GiExperimentScratchAllocation(
                    SimpleDdgiAdvancedMemoryCategory.ReceiverFeedbackSortScratch,
                    plan.Layout.SortScratchBytes,
                    // B1 capture/sort/reduce is late, after the last receiver
                    // producer. It cannot overlap the C3 schedule-to-validate
                    // interval below.
                    new GiExperimentScratchInterval(100, 106),
                    alignment);
            }
            if (guidingConfiguration.IsEnabled)
            {
                SimpleDdgiGuidingLayout layout =
                    guidingConfiguration.RuntimeRequest.Layout;
                requests[requestCount++] = new GiExperimentScratchAllocation(
                    SimpleDdgiAdvancedMemoryCategory.DirectionalGuidingBuildScratch,
                    layout.TransientWorkspace.TotalBytes,
                    // Sample precedes DDGI trace; extract/train/build/validate
                    // follow it. The shared workspace remains live across the
                    // complete transaction.
                    new GiExperimentScratchInterval(10, 40),
                    layout.StorageAlignmentBytes);
            }
            if (!GiExperimentScratchAliasing.TryCompileArenaPlan(
                    requests[..requestCount],
                    out GiExperimentScratchArenaPlan arenaPlan,
                    out failure))
            {
                return false;
            }

            return arena.TryReconcile(
                arenaPlan,
                maximumStorageBufferRange,
                memoryHeadroom,
                out failure);
        }

        private static SimpleDdgiReceiverFeedbackPlan
            RejectReceiverFeedbackForTransientArena(
                in SimpleDdgiReceiverFeedbackPlan plan,
                string failure)
        {
            GiExperimentModeState<SimpleDdgiReceiverFeedbackMode> mode =
                plan.Mode with
                {
                    EffectiveMode = SimpleDdgiReceiverFeedbackMode.Off,
                    FallbackReason = GiExperimentFallbackReason.ResourceIncomplete,
                    FallbackDetail = string.IsNullOrWhiteSpace(failure)
                        ? "advanced-gi-transient-arena-rejected"
                        : failure
                };
            return new SimpleDdgiReceiverFeedbackPlan(
                mode,
                SimpleDdgiReceiverFeedbackLayout.Empty,
                SimpleDdgiAdvancedExperimentMemoryPlan
                    .CreateReceiverFeedbackRejected(
                        GiExperimentFallbackReason.ResourceIncomplete));
        }

        private static SimpleDdgiReceiverFeedbackPlan
            CompileSimpleDdgiReceiverFeedbackPlan(
                SimpleDdgiReceiverFeedbackMode requestedMode,
                int physicalProbeCapacity,
                in SimpleDdgiReceiverFeedbackProductionWorkload
                    producerWorkload,
                uint maximumPagePublicationGeneration,
                ulong maximumStorageBufferRange,
                ulong rendererMemoryHeadroom,
                in AdvancedGiPrerequisiteGateResult prerequisiteGate,
                in AdvancedGiQualificationGateResult qualificationGate,
                string? configuredQualificationId)
        {
            if (requestedMode is SimpleDdgiReceiverFeedbackMode.Off or
                SimpleDdgiReceiverFeedbackMode.LegacyPackedReference)
            {
                return SimpleDdgiReceiverFeedbackPlanner.Compile(
                    requestedMode,
                    default,
                    ReadOnlySpan<SimpleDdgiReceiverFeedbackProducerQuota>.Empty,
                    default);
            }

            SimpleDdgiReceiverFeedbackPlan lastPlan =
                SimpleDdgiReceiverFeedbackPlan.Disabled();
            ReadOnlySpan<double> samplingProbabilities =
                [
                    1.0 / 8.0,
                    1.0 / 16.0,
                    1.0 / 32.0,
                    1.0 / 64.0,
                    1.0 / 128.0,
                    1.0 / 256.0,
                    1.0 / 512.0,
                    1.0 / 1024.0,
                    1.0 / 2048.0,
                    1.0 / 4096.0
                ];
            Span<SimpleDdgiReceiverFeedbackProducerQuota> producerQuotas =
                stackalloc SimpleDdgiReceiverFeedbackProducerQuota[
                    SimpleDdgiReceiverFeedbackProductionQuotaPlan
                        .NonOpaqueQuotaCount];
            foreach (double samplingProbability in samplingProbabilities)
            {
                if (!SimpleDdgiReceiverFeedbackProductionQuotaPlanner.TryCompile(
                        producerWorkload,
                        samplingProbability,
                        SimpleDdgiReceiverFeedbackCaptureSourceAbi
                            .MaximumUniqueGatherOwnersPerTile,
                        out SimpleDdgiReceiverFeedbackProductionQuotaPlan
                            quotaPlan,
                        out string quotaFailure))
                {
                    return new SimpleDdgiReceiverFeedbackPlan(
                        new GiExperimentModeState<
                            SimpleDdgiReceiverFeedbackMode>(
                            requestedMode,
                            SimpleDdgiReceiverFeedbackMode.Off,
                            SimpleDdgiReceiverFeedbackMode.Off,
                            SimpleDdgiReceiverFeedbackMode.Off,
                            GiExperimentFallbackReason.InvalidConfiguration,
                            quotaFailure,
                            prerequisiteGate.QualificationId),
                        SimpleDdgiReceiverFeedbackLayout.Empty,
                        SimpleDdgiAdvancedExperimentMemoryPlan
                            .CreateReceiverFeedbackRejected(
                                GiExperimentFallbackReason.InvalidConfiguration));
                }
                quotaPlan.WriteNonOpaqueQuotas(producerQuotas);
                var request = new SimpleDdgiReceiverFeedbackLayoutRequest(
                    physicalProbeCapacity,
                    producerWorkload.SourceScreenTileCount,
                    samplingProbability,
                    SimpleDdgiReceiverFeedbackCaptureSourceAbi
                        .MaximumUniqueGatherOwnersPerTile,
                    SafetyMarginRecords: quotaPlan.SafetyMarginRecords,
                    WorkgroupSize:
                        SimpleDdgiReceiverFeedbackGpuSortAbi.WorkgroupSize,
                    SortScratchBytesPerRecord: 0UL,
                    IndependentMemoryBudgetBytes:
                        SimpleDdgiReceiverFeedbackExperimentBudgetBytes,
                    RendererMemoryHeadroomBytes: rendererMemoryHeadroom,
                    MaximumStorageBufferRange: maximumStorageBufferRange,
                    MaximumPagePublicationGeneration:
                        maximumPagePublicationGeneration);
                lastPlan = SimpleDdgiReceiverFeedbackPlanner.Compile(
                    requestedMode,
                    request,
                    producerQuotas,
                    new SimpleDdgiReceiverFeedbackPrerequisites(
                        ExactBackendSupported:
                            physicalProbeCapacity > 0 &&
                            producerWorkload.SourceScreenTileCount > 0UL &&
                            maximumStorageBufferRange > 0UL,
                        PrerequisitesSatisfied:
                            AdvancedGiActivationPolicy
                                .PrerequisitesSatisfied(
                                    requestedMode,
                                    prerequisiteGate),
                        ExactQualificationPassed: qualificationGate.Passed,
                        QualificationId:
                            AdvancedGiQualificationContract.NormalizeSha256(
                                configuredQualificationId),
                        ResourcesComplete: true));
                if (lastPlan.UsesExactCompacted ||
                    lastPlan.Mode.FallbackReason is not (
                        GiExperimentFallbackReason
                            .IndependentMemoryBudgetExceeded or
                        GiExperimentFallbackReason
                            .RendererMemoryHeadroomExceeded))
                {
                    break;
                }
            }

            return lastPlan;
        }

        private SimpleDdgiReceiverFeedbackProductionWorkload
            CreateSimpleDdgiReceiverFeedbackProductionWorkload(
                Extent2D extent,
                ulong screenTileCount)
        {
            static ulong DivideRoundUp(ulong value, ulong divisor) =>
                value == 0UL ? 0UL : 1UL + (value - 1UL) / divisor;

            ulong fogWorkgroups = Settings.Fog.Enabled
                ? checked(
                    DivideRoundUp(extent.Width, 8UL) *
                    DivideRoundUp(extent.Height, 8UL))
                : 0UL;
            uint maximumParticleCount =
                Settings.Particles.Enabled &&
                Settings.GlobalIllumination.SimpleDdgiParticlesEnabled
                    ? checked((uint)Settings.Particles.MaxParticles)
                    : 0u;
            ulong reflectionCaptureTiles = 0UL;
            if (Settings.Reflections.Enabled &&
                Settings.Reflections.CaptureIncludesDdgi &&
                Settings.Reflections.MaxProbeCapturesPerFrame > 0 &&
                Settings.Reflections.MaxProbeCaptureFacesPerFrame > 0)
            {
                ulong faceTiles = checked(
                    DivideRoundUp(
                        Settings.Reflections.ProbeResolution,
                        ForwardPlusPass.SimpleDdgiReceiverGatherScale) *
                    DivideRoundUp(
                        Settings.Reflections.ProbeResolution,
                        ForwardPlusPass.SimpleDdgiReceiverGatherScale));
                reflectionCaptureTiles = checked(
                    faceTiles *
                    (ulong)Settings.Reflections.MaxProbeCapturesPerFrame *
                    (ulong)Settings.Reflections.MaxProbeCaptureFacesPerFrame);
            }

            return new SimpleDdgiReceiverFeedbackProductionWorkload(
                screenTileCount,
                fogWorkgroups,
                maximumParticleCount,
                reflectionCaptureTiles,
                SimpleDdgiReceiverFeedbackProductionWorkload
                    .DefaultMaximumTransparentLayersPerTile);
        }

        private void ObserveCompletedSimpleDdgiWorkload(int frameIndex)
        {
            if ((uint)frameIndex >= (uint)_simpleDdgiSubmittedWorkloads.Length)
                throw new ArgumentOutOfRangeException(nameof(frameIndex));

            SimpleDdgiSubmittedWorkload workload =
                _simpleDdgiSubmittedWorkloads[frameIndex];
            if (!workload.Valid)
                return;
            _simpleDdgiSubmittedWorkloads[frameIndex] = default;

            ulong farFieldSteps =
                (ulong)_completedDdgiInvestigationCounters.FarFieldStepBucket0Count * 2UL +
                (ulong)_completedDdgiInvestigationCounters.FarFieldStepBucket1Count * 6UL +
                (ulong)_completedDdgiInvestigationCounters.FarFieldStepBucket2Count * 12UL +
                (ulong)_completedDdgiInvestigationCounters.FarFieldStepBucket3Count * 24UL +
                (ulong)_completedDdgiInvestigationCounters.FarFieldStepBucket4Count * 48UL;
            ulong materialEvaluations =
                (ulong)_completedMaterialGiCounters.EstimatedDetailedTransportHitCount +
                _completedMaterialGiCounters.EstimatedCompactTransportHitCount +
                _completedMaterialGiCounters.EstimatedCorrectnessFallbackHitCount +
                _completedMaterialGiCounters.EstimatedFarFieldTransportHitCount;
            _simpleDdgiSchedulerCostModel.Observe(
                new SimpleDdgiSchedulerCostSample(
                    workload.ScheduledPrimaryRayCount,
                    workload.VisibilityRayCount,
                    _completedMaterialGiCounters.EstimatedAlphaCandidateTestCount,
                    materialEvaluations,
                    farFieldSteps));

            ulong completedHits = 0UL;
            ulong completedMisses = 0UL;
            ulong rejectedBackFaces = 0UL;
            if (_completedDdgiForwardEstimateCounters.ReadbackValid != 0)
            {
                completedHits =
                    _completedDdgiForwardEstimateCounters.TraceEnergyHitCount;
                completedMisses =
                    _completedDdgiForwardEstimateCounters.TraceEnergyMissCount;
                rejectedBackFaces =
                    _completedDdgiForwardEstimateCounters.TraceOneSidedBackFaceHitCount;
            }
            if (completedHits == 0UL && completedMisses == 0UL &&
                _completedDdgiInvestigationCounters.ReadbackValid != 0)
            {
                completedHits = _completedDdgiInvestigationCounters.SimpleTraceHitCount;
                completedMisses = _completedDdgiInvestigationCounters.SimpleTraceMissCount;
                rejectedBackFaces = 0UL;
            }
            ulong shadeableHits = completedHits > rejectedBackFaces
                ? completedHits - rejectedBackFaces
                : 0UL;
            _simpleDdgiVolumeManager?.ObserveSourceCacheWorkload(
                shadeableHits,
                completedMisses,
                rejectedBackFaces,
                workload.SourceCacheLayoutIdentity,
                workload.FrameSerial);
        }

        private void RecordSimpleDdgiSubmittedWorkload(
            int frameIndex,
            SceneRenderingData sceneData)
        {
            if ((uint)frameIndex >= (uint)_simpleDdgiSubmittedWorkloads.Length)
                throw new ArgumentOutOfRangeException(nameof(frameIndex));

            SimpleDdgiVolumeManager? manager = _simpleDdgiVolumeManager;
            _simpleDdgiSubmittedWorkloads[frameIndex] =
                manager != null && sceneData.SimpleDdgiActive != 0
                    ? new SimpleDdgiSubmittedWorkload(
                        Valid: true,
                        FrameSerial: sceneData.DdgiFrameSerial,
                        SourceCacheLayoutIdentity:
                            manager.SourceCacheAdmissionIdentity,
                        ScheduledPrimaryRayCount:
                            sceneData.DdgiScheduledPrimaryRayCount,
                        VisibilityRayCount: sceneData.DdgiVisibilityRayCount)
                    : default;
        }


        private void ScheduleReflectionProbeRecapturesFromGi(SceneRenderingData sceneData, bool simpleDdgiActive)
        {
            if (_reflectionProbeManager == null ||
                !Settings.Reflections.Enabled ||
                Settings.Reflections.Mode == ReflectionMode.Disabled ||
                sceneData.ReflectionProbeCount <= 0)
            {
                _lastReflectionProbeGiReady = false;
                _lastReflectionProbeSimpleDirtyReasonFlags = 0u;
                return;
            }

            SimpleDdgiAtmosphereCohortFeedback simpleCohort =
                simpleDdgiActive && _simpleDdgiVolumeManager is { TransportV2Active: true }
                    ? _simpleDdgiVolumeManager.CreateAtmosphereCohortFeedbackSnapshot()
                    : default;
            bool simpleCohortReady = simpleDdgiActive &&
                                     _simpleDdgiVolumeManager is { TransportV2Active: true } &&
                                     simpleCohort.ParticipatingProbeCount > 0 &&
                                     simpleCohort.StaleParticipatingProbeCount == 0 &&
                                     !simpleCohort.SourceCohortActive &&
                                     simpleCohort.SourceCohortGeneration ==
                                     simpleCohort.AdmittedSourceCohortGeneration &&
                                     simpleCohort.VisiblePublicationBoundaryComplete &&
                                     simpleCohort.MinimumPropagationBoundaryComplete &&
                                     simpleCohort.QuietPeriodComplete &&
                                     simpleCohort.PropagationGeneration ==
                                     simpleCohort.PublishedPropagationGeneration;
            bool giReady = simpleDdgiActive
                ? simpleCohortReady ||
                  (_simpleDdgiVolumeManager is { TransportV2Active: false } &&
                   sceneData.SimpleDdgiActive != 0 &&
                   sceneData.SimpleDdgiProbeCount > 0 &&
                   sceneData.SimpleDdgiAtlasFresh == 0 &&
                   sceneData.SimpleDdgiFramesSinceLastClear > 0)
                : false;
            if (giReady && !_lastReflectionProbeGiReady)
                _reflectionProbeManager.RequestRecaptureAll("ddgi-ready");

            uint dirtyReasonFlags = simpleDdgiActive ? sceneData.SimpleDdgiDirtyReasonFlags : 0u;
            if (dirtyReasonFlags != 0u && dirtyReasonFlags != _lastReflectionProbeSimpleDirtyReasonFlags)
                _reflectionProbeManager.RequestRecaptureAll("simple-ddgi-dirty");
            sceneData.ReflectionProbeCapturesQueued = _reflectionProbeManager.CapturesQueued;
            sceneData.ReflectionProbeCapturesCompleted = _reflectionProbeManager.CapturesCompleted;
            _lastReflectionProbeGiReady = giReady;
            _lastReflectionProbeSimpleDirtyReasonFlags = dirtyReasonFlags;
        }

        internal static int ResolveConfiguredSimpleDdgiPrimaryRayBudget(int configuredBudget) =>
            Math.Max(0, configuredBudget);

        internal readonly record struct SimpleDdgiFrameWork(
            int ScheduledProbeCount,
            int SourceRefreshProbeCount,
            ulong PrimaryRayCount,
            ulong SourceRayCount,
            ulong TransportRayCount,
            int PublishedProbeCount);

        internal readonly record struct SimpleDdgiSubmittedWorkload(
            bool Valid,
            ulong FrameSerial,
            ulong SourceCacheLayoutIdentity,
            ulong ScheduledPrimaryRayCount,
            ulong VisibilityRayCount);

        /// <summary>
        /// Selects the authority for per-frame work diagnostics. Resident mode
        /// has no CPU-authored queue, so only its delayed, generation-validated
        /// GPU summary can describe probe/ray work. CPU and mirror modes retain
        /// their synchronous queue counters.
        /// </summary>
        internal static SimpleDdgiFrameWork ResolveSimpleDdgiFrameWork(
            bool rayUpdateActive,
            SimpleDdgiSchedulerMode schedulerMode,
            bool gpuFeedbackValid,
            GPUSimpleDdgiSchedulerFeedback gpuFeedback,
            int cpuScheduledProbeCount,
            int cpuSourceRefreshProbeCount,
            ulong cpuPrimaryRayCount,
            ulong cpuSourceRayCount,
            ulong cpuTransportRayCount,
            int cpuPublishedProbeCount)
        {
            if (!rayUpdateActive)
                return default;

            if (schedulerMode == SimpleDdgiSchedulerMode.GpuResident &&
                gpuFeedbackValid)
            {
                return new SimpleDdgiFrameWork(
                    checked((int)Math.Min(gpuFeedback.AcceptedCount, (uint)int.MaxValue)),
                    checked((int)Math.Min(gpuFeedback.SourceProbeUsed, (uint)int.MaxValue)),
                    gpuFeedback.PrimaryRayUsed,
                    gpuFeedback.SourceAchievedRays,
                    gpuFeedback.TransportRayUsed,
                    checked((int)Math.Min(gpuFeedback.PublishedCount, (uint)int.MaxValue)));
            }

            return new SimpleDdgiFrameWork(
                Math.Max(0, cpuScheduledProbeCount),
                Math.Max(0, cpuSourceRefreshProbeCount),
                cpuPrimaryRayCount,
                cpuSourceRayCount,
                cpuTransportRayCount,
                Math.Max(0, cpuPublishedProbeCount));
        }

        private void PopulateSimpleDdgiFrameData(SceneRenderingData sceneData, bool simpleDdgiRayUpdateActive)
        {
            if (_simpleDdgiVolumeManager == null)
                return;

            GPUSimpleDdgiSchedulerFeedback schedulerFeedback =
                _simpleDdgiVolumeManager.LastGpuSchedulerFeedback;
            bool schedulerFeedbackValid =
                _simpleDdgiVolumeManager.GpuSchedulerFeedbackValid;
            SimpleDdgiFrameWork frameWork = ResolveSimpleDdgiFrameWork(
                simpleDdgiRayUpdateActive,
                _simpleDdgiVolumeManager.SchedulerMode,
                schedulerFeedbackValid,
                schedulerFeedback,
                _simpleDdgiVolumeManager.ProbesToUpdate,
                _simpleDdgiVolumeManager.SourceRefreshProbeCount,
                _simpleDdgiVolumeManager.ScheduledPrimaryRayCount,
                _simpleDdgiVolumeManager.ScheduledSourceRayCount,
                _simpleDdgiVolumeManager.ScheduledTransportRayCount,
                _simpleDdgiVolumeManager.TransportPublishedProbeCount);
            int probesToUpdate = frameWork.ScheduledProbeCount;
            ulong primaryRayCount = frameWork.PrimaryRayCount;
            int configuredRequestBudget =
                _simpleDdgiVolumeManager.SchedulerTelemetry.ConfiguredRequestBudget;
            int configuredPrimaryRayBudget = ResolveConfiguredSimpleDdgiPrimaryRayBudget(
                Settings.GlobalIllumination.DdgiProbeUpdatePrimaryRayBudget);
            sceneData.DdgiProbeVolumeCount = _simpleDdgiVolumeManager.VolumeCount;
            sceneData.DdgiProbeCount = _simpleDdgiVolumeManager.ProbeCount;
            sceneData.DdgiActiveProbeCount = _simpleDdgiVolumeManager.ActiveProbeCount;
            sceneData.DdgiRaysPerProbe = _simpleDdgiVolumeManager.RaysPerProbe;
            sceneData.DdgiProbesUpdated = probesToUpdate;
            sceneData.SimpleDdgiActive = _simpleDdgiVolumeManager.ProbeCount > 0 ? 1 : 0;
            sceneData.SimpleDdgiSchedulerMode = _simpleDdgiVolumeManager.SchedulerMode;
            sceneData.SimpleDdgiSchedulerReady = _simpleDdgiVolumeManager.GpuScheduler.IsReady ? 1 : 0;
            sceneData.SimpleDdgiSchedulerFeedbackValid =
                schedulerFeedbackValid ? 1 : 0;
            sceneData.SimpleDdgiSchedulerFeedbackFrameSerial =
                _simpleDdgiVolumeManager.GpuSchedulerFeedbackFrameSerial;
            sceneData.SimpleDdgiSchedulerFeedbackConsideredCount =
                schedulerFeedback.ConsideredCount;
